const app=document.querySelector('#app'),dialog=document.querySelector('#editor');
const tables=['influencer_marketing','orders','customers','expenses','purchases','salaries','order_payments','salary_payments','alterations','inventory','order_items','studio_pieces','jobs','tasks','events','salary_profiles','salary_payouts','purchase_payments'];
let data=Object.fromEntries(tables.map(k=>[k,[]])),view='home',search='',orderFilter='pending',loading=false;
let recordPageIndex=0,moneyPageIndex=0,moneyPageCount=1;
let homePreset='month',homeFrom=today().slice(0,7)+'-01',homeTo=today(),homeMetrics=null,homeRangeBusy=false,homeRangeError='',homeRequest=0,paymentFilter='all';
let selectedExpenseMonth=today().slice(0,7);
let selectedMoneyMonth=today().slice(0,7),monthlyMoney=null;
let expenseFilters={from:'',to:'',category:'',status:'',sort:'date',direction:-1,page:0,search:''},sheetRows=[],expenseFilterOpen=false;
let profile={},overview={},people=[],members=[],showAllUpcoming=false,group='home',studioTab='studio_pieces',moneyTab='payments',expenseTab='expenses',moreTab='tasks';
const can=p=>profile.role==='owner'||profile.permissions?.includes(p);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:0,maximumFractionDigits:2}).format(n(v));
const date=v=>v?new Date(v+'T12:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'—';
const customer=o=>data.customers.find(c=>c.id===o.customer_id)?.name||o.customer_name||'—';
const order=id=>data.orders.find(o=>o.id===id);
const orderLabel=id=>{const o=order(id);return o?`${o.reference} · ${customer(o)}`:'Stock / general';};
const badge=s=>{const tone=['Paid','Delivered','Returned','Completed','Low priority'].includes(s)?'sage':['Overdue','High priority','Unpaid'].includes(s)?'pink':['Due soon','Part paid','Medium priority','Pending','Delivery'].includes(s)?'peach':['Voided','Cancelled'].includes(s)?'neutral':'lavender';return `<span class="badge tone-${tone}">${esc(s)}</span>`;};
const action=(label,attrs,primary=false)=>`<button ${attrs} class="${primary?'primary':''}">${esc(label)}</button>`;
function notify(message){const node=document.querySelector('#toast');node.textContent=message;node.classList.add('visible');setTimeout(()=>node.classList.remove('visible'),4500);}
function empty(title,detail='Add your first record using the button above.'){return `<div class="empty"><span>◇</span><h3>${esc(title)}</h3><p>${esc(detail)}</p></div>`;}
function cards(items){return `<section class="metrics">${items.map(([label,value,note])=>`<article><span>${esc(label)}</span><strong>${esc(value)}</strong>${note?`<small>${esc(note)}</small>`:''}</article>`).join('')}</section>`;}
function table(headers,rows){return rows.length?`<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(cells=>`<tr>${cells.map((c,i)=>`<td data-label="${esc(headers[i]||'')}" ${headers[i]?'':'class="record-actions"'}><div class="cell-value">${c??'—'}</div></td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('No records to show');}
function section(title,body,extra=''){return `<section class="panel"><div class="panel-heading"><h2>${esc(title)}</h2>${extra}</div>${body}</section>`;}
const moneyCell=value=>`<span class="money">${money(value)}</span>`;
function login(message=''){
 app.innerHTML=`<main class="login"><div class="login-brand"><span class="monogram">M</span><p>LABEL MUSKAN</p><h1>Your studio,<br>in order.</h1><p class="muted">Orders, people, and everyday details.</p></div><form id="login"><span class="eyebrow">TEAM WORKSPACE</span><h2>Welcome back</h2><p>Sign in to Label Muskan operations.</p><label>Email<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><p class="form-error" role="alert">${esc(message)}</p><button class="primary" type="submit">Sign in →</button><small>For approved studio team members.</small></form></main>`;
 document.querySelector('#login').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,b=form.querySelector('button');b.disabled=true;try{const f=new FormData(form);await signIn(f.get('email'),f.get('password'));await load();}catch(err){if(form.isConnected)form.querySelector('.form-error').textContent=err.message;}finally{b.disabled=false;}};
}
async function load(silent=false){
 if(loading)return;loading=true;if(!silent)app.innerHTML='<main class="loading">Opening your studio workspace…</main>';
 try{
  if(!getSession()){login();return;}
  await reloadData();render();
 }catch(err){if(!getSession()){login(err.message);return;}if(silent){notify('Refresh failed: '+err.message);return;}
  app.innerHTML=`<main class="loading"><h2>Unable to open the workspace</h2><p>${esc(err.message)}</p><button id="retry">Try again</button><button id="logout">Sign out</button></main>`;document.querySelector('#retry').onclick=()=>load();
 document.querySelector('#logout').onclick=logout;
 }finally{loading=false;}
}
async function logout(){dialog.close();await signOut();data=Object.fromEntries(tables.map(k=>[k,[]]));login();}

const navigation=[['home','Home','◈'],['orders','Orders','▤'],['spending','Expenses','↗'],['money','Money','₹'],['influencer_marketing','Influencer Marketing','✧'],['customers','Clients','○'],['studio','Studio','◇'],['more','More','⋯']];
const permissions={influencer_marketing:'marketing',home:'home',orders:'orders',customers:'clients',studio_pieces:'studio',jobs:'production',tasks:'tasks',events:'calendar',payments:'payments',expenses:'expenses',purchases:'purchases',salaries:'salaries',salary_profiles:'salaries',inventory:'owner',members:'owner',planned:'owner',deleted:'owner'};
const visibleGroup=k=>k==='studio'?['studio','production','calendar'].some(can):k==='spending'?['expenses','purchases','salaries'].some(can):k==='money'?can('payments'):k==='more'?['tasks','calendar','owner'].some(can):can(permissions[k]);
function render(){
 if(!visibleGroup(group))group=navigation.find(([k])=>visibleGroup(k))?.[0]||'more';
 let tabs=[];
 if(group==='studio')tabs=[['studio_pieces','Pieces'],['jobs','Karigar / Production'],['events','Calendar']];
 if(group==='money')tabs=[['payments','Client payments']];
 if(group==='spending')tabs=[['expenses','Expenses'],['salaries','Salaries'],['purchases','Purchases']];
 if(group==='more')tabs=[['tasks','Tasks'],['events','Calendar'],['members','Team access'],['inventory','Stock register'],['planned','Planned modules'],['deleted','Deleted entries']];
 tabs=tabs.filter(([k])=>can(permissions[k]));
 if(tabs.length){const current=group==='studio'?studioTab:group==='money'?moneyTab:group==='spending'?expenseTab:moreTab;view=tabs.some(([k])=>k===current)?current:tabs[0][0];}else view=group;
 const title=group==='spending'?'EXPENSES':navigation.find(([k])=>k===group)?.[1]||'Workspace';
 const adds=[['orders','New order',can('orders')&&can('payments')],['customers','New client',can('clients')],['tasks','Task',can('tasks')],['expenses','Expense',can('expenses')],['purchases','Purchase',can('purchases')],['studio_pieces','Studio piece',can('studio')],['payment','Payment',can('payments')]].filter(x=>x[2]);
 app.innerHTML=`<aside><div class="brand"><span class="monogram">M</span><div>LABEL MUSKAN<small>Studio operations</small></div></div><span class="nav-label">WORKSPACE</span><nav>${navigation.filter(([k])=>visibleGroup(k)).map(([key,title,icon])=>`<button data-view="${key}" class="${group===key?'active':''}"><span>${icon}</span>${title}</button>`).join('')}</nav><div class="sidebar-bottom"><span class="connection-dot"></span> ${esc(profile.name||profile.role)}<small>${esc(getSession().user.email)}</small><button id="logout">Sign out ↗</button></div></aside><main class="workspace"><header><div><span class="eyebrow">LABEL MUSKAN / STUDIO</span><h1>${title}</h1></div><div class="header-actions"><span class="today">${date(today())}</span><button id="refresh" aria-label="Refresh">↻</button>${adds.length&&group!=='spending'?`<details class="quick-add"><summary>+ ADD</summary><div>${adds.map(([k,l])=>action('+ '+l,`data-add="${k}"`)).join('')}</div></details>`:''}</div></header>${tabs.length&&!['money','spending'].includes(group)?`<div class="subnav">${tabs.map(([k,l])=>action(l,`data-tab="${k}"`,view===k)).join('')}</div>`:''}<div id="content">${content()}</div><footer>Label Muskan · Studio workspace<span>INR · India time</span></footer></main>`;
 wire();
}
let searchTimer;
function bindRecords(root=document){
 wireDelete(root);root.querySelectorAll('[data-phone-edit]').forEach(b=>b.onclick=()=>editClientPhone(b.dataset.phoneEdit));root.querySelectorAll('[data-record-page]').forEach(b=>b.onclick=()=>{recordPageIndex+=Number(b.dataset.recordPage);const records=document.querySelector('#records');records.innerHTML=recordRows();bindRecords(records);records.scrollIntoView({block:'start',behavior:'smooth'});});
 root.querySelectorAll('[data-done]').forEach(b=>b.onchange=async()=>{try{await save('tasks',{done:b.checked},b.dataset.done);await reloadData();render();}catch(e){b.checked=!b.checked;notify(e.message);}});
 root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.module,data[b.dataset.module].find(r=>r.id===b.dataset.edit)));
 root.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>orderDetail(b.dataset.detail));
 root.querySelectorAll('[data-delivery]').forEach(b=>b.onclick=()=>deliveryConfirmation(b.dataset.delivery,b.dataset.delivered==='true'));
 root.querySelectorAll('[data-client]').forEach(b=>b.onclick=()=>clientDetail(b.dataset.client));
 root.querySelectorAll('[data-payment]').forEach(b=>b.onclick=()=>paymentForm('order',b.dataset.payment));
 root.querySelectorAll('[data-salary-payment]').forEach(b=>b.onclick=()=>paymentForm('salary',b.dataset.salaryPayment));
 root.querySelectorAll('[data-salary-detail]').forEach(b=>b.onclick=()=>salaryDetail(b.dataset.salaryDetail));
}
function wire(){
 wirePlan();wireExpenseSheet();wireMarketing();wireHomeRange();
 document.querySelectorAll('[data-payment-filter]').forEach(b=>b.onclick=()=>{paymentFilter=b.dataset.paymentFilter;moneyPageIndex=0;render();});
 document.querySelectorAll('[data-cash-page]').forEach(b=>b.onclick=()=>{moneyPageIndex+=Number(b.dataset.cashPage);render();document.querySelector('.money-entries')?.scrollIntoView({block:'start',behavior:'smooth'});});
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{group=b.dataset.view;if(group==='spending')expenseTab='expenses';recordPageIndex=0;moneyPageIndex=0;search='';orderFilter='pending';render();});
 document.querySelector('#logout').onclick=logout;document.querySelector('#refresh').onclick=()=>load(true);
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(group==='studio')studioTab=b.dataset.tab;else if(group==='money')moneyTab=b.dataset.tab;else if(group==='spending'){expenseTab=b.dataset.tab;expenseFilters={from:'',to:'',category:'',status:'',sort:'date',direction:-1,page:0,search:''};}else moreTab=b.dataset.tab;search='';recordPageIndex=0;orderFilter='pending';render();});
 document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>b.dataset.add==='payment'?choosePayment():edit(b.dataset.add));bindRecords();

 document.querySelectorAll('[data-money-month]').forEach(b=>b.onclick=async()=>{const previous=selectedMoneyMonth;selectedMoneyMonth=shiftMonth(selectedMoneyMonth,Number(b.dataset.moneyMonth));expenseFilters.page=0;moneyPageIndex=0;try{await loadMoneySummary();render();}catch(err){selectedMoneyMonth=previous;notify(err.message);}});
 document.querySelectorAll('[data-profile-payment]').forEach(b=>b.onclick=()=>profilePayment(b.dataset.profilePayment));
 document.querySelectorAll('[data-purchase-payment]').forEach(b=>b.onclick=()=>purchasePayment(b.dataset.purchasePayment));
 document.querySelectorAll('[data-money-void]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await save(b.dataset.table,{voided:true},b.dataset.moneyVoid);await reloadData();render();notify('Payment voided');}catch(err){b.disabled=false;notify(err.message);}});
 document.querySelector('#view-all-upcoming')?.addEventListener('click',()=>{showAllUpcoming=!showAllUpcoming;render();});
 document.querySelector('#quick-task')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),b=e.currentTarget.querySelector('button');b.disabled=true;try{await save('tasks',{title:f.get('title'),task_date:f.get('task_date')||today(),category:'Studio',assigned_user_id:profile.user_id,customer_id:f.get('customer_id')||null,order_id:f.get('order_id')||null});await reloadData();render();notify(f.get('task_date')&&f.get('task_date')!==today()?'Task saved for '+date(f.get('task_date')):'Task added');}catch(err){notify(err.message);b.disabled=false;}});
 const taskForm=document.querySelector('#quick-task');if(taskForm){const client=taskForm.elements.customer_id,select=taskForm.elements.order_id;if(client&&select){client.onchange=()=>{select.innerHTML='<option value="">None</option>'+sortOrders(data.orders.filter(o=>!client.value||o.customer_id===client.value)).map(o=>`<option value="${o.id}">${esc(orderLabel(o.id))}</option>`).join('');};select.onchange=()=>{const o=order(select.value);if(o)client.value=o.customer_id||'';};}}
 document.querySelectorAll('[data-member]').forEach(b=>b.onclick=()=>memberForm(members.find(m=>m.user_id===b.dataset.member)));
 document.querySelector('#add-member')?.addEventListener('click',()=>memberForm());
 document.querySelector('#agenda-date')?.addEventListener('change',e=>{agendaDate=e.target.value;render();});

 document.querySelector('#search')?.addEventListener('input',e=>{search=e.target.value;recordPageIndex=0;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const records=document.querySelector('#records');if(!records)return;records.innerHTML=recordRows();bindRecords(records);},120);});
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{orderFilter=b.dataset.filter;recordPageIndex=0;render();});

}
function planKey(){return 'lm-planned-modules:'+profile.user_id;}
function planChoices(){try{return JSON.parse(localStorage.getItem(planKey())||'{}')||{};}catch{return {};}}
function plannedPage(){const choices=planChoices(),picked=plannedModules.filter(m=>choices[m.id]);return `<div class="planned-page">${section('Your next studio chapter',`<div class="plan-intro"><p>Choose the modules you would like us to build next.</p><small>Ideas only · ${picked.length} selected · Saved on this device</small>${picked.length?action('Download shortlist','id="download-plan"'):''}</div>`)}<div class="plan-groups">${moduleGroups.map((g,i)=>`<details class="plan-group" ${i===0?'open':''}><summary>${esc(g.name)}<span>${g.modules.filter(([id])=>choices[id]).length} / ${g.modules.length}</span></summary><div class="plan-options">${g.modules.map(([id,title,description,scenario])=>`<article class="plan-option ${choices[id]?'chosen':''}"><div><h3>${esc(title)}</h3><p>${esc(description)}</p><small>${esc(scenario)}</small></div><label>Build priority<select data-plan-choice="${id}" aria-label="Build priority for ${esc(title)}"><option value="" ${!choices[id]?'selected':''}>Not chosen</option><option value="next" ${choices[id]==='next'?'selected':''}>Build next</option><option value="later" ${choices[id]==='later'?'selected':''}>Consider later</option></select></label></article>`).join('')}</div></details>`).join('')}</div></div>`;}
function wirePlan(){document.querySelectorAll('[data-plan-choice]').forEach(select=>select.onchange=()=>{const choices=planChoices();if(select.value)choices[select.dataset.planChoice]=select.value;else delete choices[select.dataset.planChoice];try{localStorage.setItem(planKey(),JSON.stringify(choices));const openGroups=[...document.querySelectorAll('.plan-group')].map(g=>g.open),scrollY=window.scrollY,id=select.dataset.planChoice;render();document.querySelectorAll('.plan-group').forEach((g,i)=>g.open=openGroups[i]);window.scrollTo(0,scrollY);document.querySelector(`[data-plan-choice="${id}"]`)?.focus({preventScroll:true});}catch{notify('Unable to save choices on this device.');}});document.querySelector('#download-plan')?.addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([shortlistText(planChoices())],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='Label-Muskan-Planned-Modules.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}

function content(){if(view==='deleted')return deletedPage();if(group==='influencer_marketing')return marketingPage();if(view==='planned')return plannedPage();if(group==='money')return moneyPage();if(group==='spending')return expensesPage();if(view==='home')return home();if(view==='members')return memberPage();if(view==='events')return calendarPage();if(view==='payments')return paymentsPage();return recordPage();}
const due=o=>o.next_delivery||o.due_date;
const itemsFor=id=>data.order_items.filter(i=>i.order_id===id);
function deliveryRows(orders,recentFirst=false){return orders.length?`<div class="compact-orders">${(recentFirst?sortOrdersLatestInvoice(orders):sortOrders(orders)).map(o=>{const products=itemsFor(o.id),delivered=o.status==='Delivered',finance=can('payments'),remaining=finance?balance(data,o):0,paid=finance?received(data,o.id):0,advance=finance?sum(paymentsFor(data,o.id).filter(p=>p.kind==='Advance')):0;return `<article class="compact-order order-studio-card"><div class="order-card-heading"><div><span class="eyebrow">${o.invoice_number?`INVOICE #${esc(o.invoice_number)} · `:''}ORDER #${esc(o.reference)}</span><h3>${esc(customer(o))}</h3></div>${finance?badge(paymentStatus(data,o)):badge(delivered?'Delivered':'Active')}</div><div class="compact-product">${products.length>1?`<details><summary>${products.length} outfits · ${esc(o.status)}</summary><div class="compact-product-list">${products.map(i=>`<p>${esc(i.name)} ${badge(i.status)}</p>`).join('')}</div></details>`:`<span>${esc(products[0]?.name||o.product||'Outfit')}</span>${badge(products[0]?.status||o.status)}`}</div><div class="order-deadline">${due(o)?`<span>${date(due(o))}</span>${badge(!delivered&&due(o)<today()?'Overdue':!delivered&&due(o)<=addDays(today(),3)?'Due soon':delivered?'Delivered':'Delivery')}`:'<span>Delivery date not set</span>'}</div>${finance?`<div class="order-financials"><div><span>Total</span><strong>${money(o.amount)}</strong></div><div><span>Advance</span><strong>${money(advance)}</strong></div><div><span>Paid to date</span><strong>${money(paid)}</strong></div><div class="${remaining>0?'balance-due':'balance-clear'}"><span>Outstanding</span><strong>${money(remaining)}</strong></div></div>`:''}<div class="compact-order-actions">${finance&&remaining>0&&o.status!=='Cancelled'?action('+ Add Payment',`type="button" data-payment="${o.id}"`,true):''}${action('Open order',`type="button" data-detail="${o.id}"`)}${can('orders')?action('Edit',`type="button" data-edit="${o.id}" data-module="orders"`):''}${can('orders')&&o.status!=='Cancelled'?action(delivered?'Undo delivery':'Mark delivered',`type="button" data-delivery="${o.id}" data-delivered="${!delivered}"`):''}</div></article>`;}).join('')}</div>`:empty('No orders to show');}
function deliveryConfirmation(id,delivered){const o=order(id),remaining=can('payments')?balance(data,o):null;const form=openModal(delivered?'Mark order Delivered?':'Undo delivery?',`<p class="delivery-confirm-title">#${esc(o.reference)} · ${esc(customer(o))}</p>${delivered&&remaining>0?`<p class="delivery-balance-reminder">Outstanding: <strong>${money(remaining)}</strong></p>`:''}<p class="helper">${delivered?'All active products will be marked Delivered. Payment records stay unchanged.':o.delivery_previous_stages?'The saved production stages will be restored. Payment records stay unchanged.':'This order has no saved earlier stages. It will reopen at Ready. Payment records stay unchanged.'}</p>`,'',async()=>{await rpc('set_order_delivery',{p_id:id,p_delivered:delivered});});form.querySelector('[type=submit]').textContent=delivered?'Confirm delivery':'Confirm undo';}

function taskRows(rows){return rows.length?`<div class="task-list">${rows.sort((a,b)=>a.task_date.localeCompare(b.task_date)||(a.task_time||'').localeCompare(b.task_time||'')).map(t=>`<div class="task-row ${t.done?'complete':''} ${t.priority?'priority-'+esc(t.priority.toLowerCase()):''}"><input type="checkbox" aria-label="Complete ${esc(t.title)}" data-done="${t.id}" ${t.done?'checked':''} ${can('tasks')?'':'disabled'}><div><b>${esc(t.title)}</b><small>${esc(t.category)} · ${date(t.task_date)} ${esc(t.task_time?.slice(0,5)||'')}${t.assigned_user_id?` · ${esc(people.find(p=>p.user_id===t.assigned_user_id)?.name||'Team')}`:''}</small></div>${can('tasks')?action('Edit',`data-edit="${t.id}" data-module="tasks"`):''}</div>`).join('')}</div>`:empty('A clear day','Add a fitting, pickup, courier or studio task.');}
function productionSummary(){const live=data.jobs.filter(j=>['Pending','In Progress'].includes(j.status)),pieces=[...data.order_items.filter(i=>activeOrder(order(i.order_id)||{})),...data.studio_pieces];return simpleSummary([['With tailor',live.filter(j=>j.kind==='Tailor').length],['With embroidery / handwork',live.filter(j=>j.kind==='Embroidery / Handwork').length],['With dyer',live.filter(j=>j.kind==='Dyer').length],['Fitting pending',pieces.filter(i=>i.status==='Fitting').length],['Alterations pending',pieces.filter(i=>i.status==='Alteration').length]]);}
function homeChecklist(rows){return rows.length?`<div class="home-checklist">${rows.sort((a,b)=>Number(a.done)-Number(b.done)).map(t=>{const client=data.customers.find(c=>c.id===t.customer_id)?.name,linked=t.order_id?orderLabel(t.order_id):client;return `<div class="home-check-row ${t.done?'complete':''} ${t.priority?'priority-'+esc(t.priority.toLowerCase()):''}"><label><input type="checkbox" data-done="${t.id}" aria-label="Complete ${esc(t.title)}" ${t.done?'checked':''} ${can('tasks')?'':'disabled'}><span><b>${esc(t.title)}</b>${linked?`<small>${esc(linked)}</small>`:''}</span></label>${can('tasks')?`<button aria-label="Edit ${esc(t.title)}" data-edit="${t.id}" data-module="tasks">⋯</button>`:''}</div>`;}).join('')}</div>`:'<p class="home-empty">No tasks for today.</p>';}
function home(){const day=today(),active=data.orders.filter(activeOrder);return `<div class="mobile-home">`+section("Today's to-do",homeChecklist(data.tasks.filter(t=>t.task_date===day))+(can('tasks')?`<form id="quick-task" class="home-task-form"><div class="home-task-input"><input name="title" placeholder="Add a task…" aria-label="New task" required maxlength="300"><button class="primary">+ Add</button></div><details class="task-links"><summary>Link client, order or date</summary><div class="form-grid">${can('clients')?field(['customer_id','Client (optional)','client']):''}${field(['order_id','Order (optional)','order'])}${field(['task_date','Date (optional)','date'])}</div></details></form>`:''))+section('Upcoming deliveries & fittings',upcomingRows(active))+section('Orders',`<div class="quiet-stats home-order-stats">${[['Due today',active.filter(o=>due(o)===day).length],['Next 3 days',active.filter(o=>due(o)>day&&due(o)<=addDays(day,3)).length],['Active orders',active.length]].map(([l,v])=>`<div><strong>${v}</strong><span>${l}</span></div>`).join('')}</div>`)+homeMoneyPanel()+`</div>`;}
async function loadHomeMetrics(){if(!can('home'))return;try{const [start,end]=overviewRange(homePreset,homeFrom,homeTo);homeMetrics=await rpc('range_money',{p_from:start,p_to:end});homeRangeError='';}catch(e){homeMetrics=null;homeRangeError=e.message;}}
function homeMoneyPanel(){const names={month:'This month',last:'Last month',all:'All months'},values=homeMetrics;return section(names[homePreset],`<div class="date-filter-tabs" role="group" aria-label="Home summary period">${Object.entries(names).map(([k,l])=>action(l,`type="button" data-home-period="${k}" aria-pressed="${homePreset===k}"`,homePreset===k)).join('')}</div>${homePreset==='custom'?`<form id="home-custom-range" class="custom-date-range"><label>From<input name="from" type="date" required value="${esc(homeFrom)}"></label><label>To<input name="to" type="date" required value="${esc(homeTo)}"></label><button class="primary" ${homeRangeBusy?'disabled':''}>Apply</button></form>`:''}${homeRangeBusy?'<p class="home-empty" role="status">Updating totals…</p>':homeRangeError?`<p class="home-empty danger" role="alert">${esc(homeRangeError)}</p>`:values?`<div class="home-month-stats">${[['Sales',values.sales],['Collected',values.collected],['Client outstanding',values.outstanding]].map(([l,v])=>`<div><span>${l}</span><strong>${money(v)}</strong></div>`).join('')}</div><p class="summary-caption">${date(values.from)} – ${date(values.to)} · Outstanding at period end</p>`:''}`);}
function wireHomeRange(){const refresh=async()=>{const token=++homeRequest;homeRangeBusy=true;homeRangeError='';render();try{const [start,end]=overviewRange(homePreset,homeFrom,homeTo);const result=await rpc('range_money',{p_from:start,p_to:end});if(token===homeRequest)homeMetrics=result;}catch(e){if(token===homeRequest)homeRangeError=e.message;}finally{if(token===homeRequest){homeRangeBusy=false;if(group==='home')render();}}};document.querySelectorAll('[data-home-period]').forEach(b=>b.onclick=()=>{homePreset=b.dataset.homePeriod;if(homePreset==='custom'){homeRequest++;homeRangeBusy=false;homeMetrics=null;homeRangeError='';render();}else refresh();});document.querySelector('#home-custom-range')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);homeFrom=f.get('from');homeTo=f.get('to');refresh();});}
const whatsappIcon='<svg viewBox="0 0 24 24" width="19" height="19" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M20.5 11.5a8.5 8.5 0 0 1-12.7 7.4L3 20.5l1.6-4.8A8.5 8.5 0 1 1 20.5 11.5Z"/><path d="M8 7.5c-.8 1.5 1 5.8 4.5 7.5 1.7.8 2.8.5 3.5-.8l-2.3-1.4-1 1c-1.8-.6-3-1.8-3.5-3.5l1-1L9 7.5Z"/></svg>';
function clientCard(c){const url=whatsappURL(c.phone),orders=data.orders.filter(o=>o.customer_id===c.id);return `<article class="compact-client client-studio-card"><div><button type="button" class="client-name" data-client="${c.id}">${esc(c.name)}</button><span>${esc(c.phone||'No phone number')}</span><small>${orders.length} ${orders.length===1?'order':'orders'}</small></div><div class="client-upfront-actions">${can('clients')?action(c.phone?'Edit number':'+ Add number',`type="button" data-phone-edit="${c.id}"`):''}${url?`<a class="whatsapp-link" href="${url}" target="_blank" rel="noopener noreferrer" aria-label="WhatsApp ${esc(c.name)}">${whatsappIcon}<span>WhatsApp</span></a>`:''}</div></article>`;}
function editClientPhone(id){const c=data.customers.find(r=>r.id===id);if(!c||!can('clients'))return;openModal('Edit phone number',`<p class="form-client-name">${esc(c.name)}</p><div class="form-grid">${field(['phone','Phone number','tel'],c)}</div><p class="helper">Include the country code for international numbers.</p>`,'',async f=>{await save('customers',{phone:String(f.get('phone')||'').trim()||null},id);});}
function upcomingRows(active){const day=today(),rows=[];active.forEach(o=>{if(due(o)>=day)rows.push({o,day:due(o),kind:'Delivery'});if(o.fitting_date>=day)rows.push({o,day:o.fitting_date,kind:'Fitting'});});rows.sort((a,b)=>a.day.localeCompare(b.day)||a.o.reference.localeCompare(b.o.reference));const visible=showAllUpcoming?rows:rows.slice(0,2);return visible.length?`<div class="upcoming-cards">${visible.map(({o,day,kind})=>`<button class="upcoming-card" data-detail="${o.id}"><time datetime="${day}">${date(day)}</time><b>${esc(customer(o))} · Order #${esc(o.reference)}</b><span class="upcoming-tags"><span class="badge ${kind==='Fitting'?'fitting-tag':'delivery-tag'}">${kind}</span><span class="upcoming-stage">${esc(o.status)}</span></span></button>`).join('')}</div>${rows.length>2?`<button id="view-all-upcoming" class="view-all-upcoming">${showAllUpcoming?'Show less ↑':'View all →'}</button>`:''}`:'<p class="home-empty">No upcoming deliveries or fittings.</p>';}
function simpleSummary(rows){return `<dl class="summary">${rows.map(([l,v])=>`<div><dt>${esc(l)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`;}
function recordPage(){const definition=definitions[view];if(!definition)return empty('No sections assigned','Ask Muskan to assign the sections you need.');const addAllowed=can(permissions[view])&&(view!=='orders'||can('payments'));return (view==='jobs'?section('Where garments are now',productionSummary()):'')+`<section class="panel"><div class="table-tools"><label class="search"><span>⌕</span><input id="search" type="search" placeholder="Search ${definition.title.toLowerCase()}" aria-label="Search" value="${esc(search)}"></label>${addAllowed?action(view==='customers'?'+ NEW CLIENT':view==='orders'?'+ NEW ORDER':'+ '+definition.singular,`data-add="${view}"`,true):''}${view==='orders'?`<div class="filters">${[['pending','Active'],['today','Today'],['soon','Next 3 days'],['overdue','Overdue'],['delivered','Delivered'],['all','All']].map(([k,l])=>action(l,`data-filter="${k}"`,orderFilter===k)).join('')}</div>`:''}</div><div id="records">${recordRows()}</div></section>`;}
function recordRows(){const html=recordRowsHTML();return html+(recordPageTotal>1?`<div class="record-pagination"><button type="button" data-record-page="-1" ${recordPageIndex===0?'disabled':''}>Previous</button><span>${recordPageIndex+1} / ${recordPageTotal}</span><button type="button" data-record-page="1" ${recordPageIndex>=recordPageTotal-1?'disabled':''}>Next</button></div>`:'');}
let recordPageTotal=1;
function pageRecords(rows){recordPageTotal=Math.max(1,Math.ceil(rows.length/30));recordPageIndex=Math.min(recordPageIndex,recordPageTotal-1);return rows.slice(recordPageIndex*30,(recordPageIndex+1)*30);}
function recordRowsHTML(){
 let records=data[view].filter(r=>Object.values(r).some(v=>String(v??'').toLowerCase().includes(search.toLowerCase()))||(r.customer_id&&customer(r).toLowerCase().includes(search.toLowerCase()))||(r.order_id&&orderLabel(r.order_id).toLowerCase().includes(search.toLowerCase())));
 const editButton=r=>action('Edit',`data-edit="${r.id}" data-module="${view}"`);
 if(view==='orders'){
  const day=today();records=sortOrdersLatestInvoice(records).filter(o=>orderFilter==='all'||orderFilter==='delivered'&&o.status==='Delivered'||orderFilter==='pending'&&activeOrder(o)||orderFilter==='today'&&activeOrder(o)&&due(o)===day||orderFilter==='soon'&&activeOrder(o)&&due(o)>day&&due(o)<=addDays(day,3)||orderFilter==='overdue'&&activeOrder(o)&&due(o)&&due(o)<day);
  return deliveryRows(pageRecords(records),true);
 }
 records.sort((a,b)=>view==='customers'||view==='inventory'?String(a.name).localeCompare(String(b.name)):view==='studio_pieces'?String(a.collection||'').localeCompare(String(b.collection||'')):view==='tasks'?String(a.task_date).localeCompare(String(b.task_date)):view==='alterations'?String(a.expected_date||'9999').localeCompare(String(b.expected_date||'9999')):String(b[{expenses:'expense_date',purchases:'purchase_date',salaries:'period_start',jobs:'given_date'}[view]||'created_at']||'').localeCompare(String(a[{expenses:'expense_date',purchases:'purchase_date',salaries:'period_start',jobs:'given_date'}[view]||'created_at']||'')));records=pageRecords(records);
 if(view==='expenses')return table(['Date','Description','Category','Amount','Paid by','Mode','Order',''],records.sort((a,b)=>b.expense_date.localeCompare(a.expense_date)).map(r=>[date(r.expense_date),esc(r.description),esc(r.category),moneyCell(r.amount),esc(r.paid_by||'—'),esc(r.payment_mode),esc(orderLabel(r.order_id)),editButton(r)]));
 if(view==='purchases')return table(['Date','Vendor / item','Category','Quantity','Amount','For','Payment',''],records.sort((a,b)=>b.purchase_date.localeCompare(a.purchase_date)).map(r=>[date(r.purchase_date),`<b>${esc(r.vendor)}</b><small>${esc(r.item)}</small>`,esc(r.category),esc(r.quantity),moneyCell(r.amount),esc(r.collection||data.studio_pieces.find(p=>p.id===r.studio_piece_id)?.name||orderLabel(r.order_id)),badge(r.status),editButton(r)]));
 if(view==='salaries')return table(['Staff / period','Frequency','Salary','Deduction','Paid','Advance','Balance',''],records.sort((a,b)=>b.period_start.localeCompare(a.period_start)).map(s=>{const payments=salaryPayments(data,s.id);return [`<b>${esc(s.staff_name)}</b><small>${date(s.period_start)} – ${date(s.period_end)}</small>`,esc(s.frequency),moneyCell(s.salary),moneyCell(s.deduction),moneyCell(sum(payments.filter(p=>p.kind==='Salary'))),moneyCell(sum(payments.filter(p=>p.kind==='Advance'))),moneyCell(salaryBalance(data,s)),action('Open',`data-salary-detail="${s.id}"`)];}));
 if(view==='customers')return records.length?`<div class="compact-clients">${records.map(clientCard).join('')}</div>`:empty('No clients to show');
 if(view==='alterations')return table(['Order / client','Issue','Received','Assigned','Expected','Status','Cost',''],records.sort((a,b)=>(a.expected_date||'9999').localeCompare(b.expected_date||'9999')).map(r=>[esc(orderLabel(r.order_id)),esc(r.issue),date(r.received_date),esc(r.assigned_to),date(r.expected_date),badge(r.status),moneyCell(r.additional_cost),editButton(r)]));
 if(view==='tasks')return taskRows(records);
 if(view==='studio_pieces')return table(['Collection / piece','For','Stage','Due / shoot','Assigned',''],records.sort((a,b)=>(a.collection||'').localeCompare(b.collection||'')).map(r=>[`<b>${esc(r.collection||'Studio')}</b><small>${esc(r.name)}</small>`,esc(r.kind),badge(r.status),`${date(r.due_date)}${r.shoot_date?`<small>Shoot · ${date(r.shoot_date)}</small>`:''}`,esc(r.assigned_to),editButton(r)]));
 if(view==='jobs')return table(['Karigar / work','Garment','Given','Due','Status',...(can('expenses')?['Payment']:[]),''],records.map(r=>[`<b>${esc(r.karigar)}</b><small>${esc(r.work)} · ${esc(r.kind)}</small>`,esc(r.order_item_id?productLabel(r.order_item_id):data.studio_pieces.find(p=>p.id===r.studio_piece_id)?.name),date(r.given_date),date(r.due_date),badge(r.status),...(can('expenses')?[badge(r.payment_status)]:[]),editButton(r)]));
 return table(['Item / SKU','Colour','Available','Unit','Unit cost','Vendor',''],records.map(r=>[`<b>${esc(r.name)}</b><small>${esc(r.sku)}</small>`,esc(r.colour),`${esc(r.quantity)}${r.quantity<=r.reorder_level?'<small class="danger">Low stock</small>':''}`,esc(r.unit),moneyCell(r.cost),esc(r.vendor),editButton(r)]));
}
function paymentsPage(){const day=today(),[ws,we]=weekRange(day),rows=sortOrders(data.orders.filter(o=>o.status!=='Cancelled'&&(orderFilter==='all'||balance(data,o)>0))).filter(o=>orderFilter==='today'?o.payment_due_date===day:orderFilter==='week'?inRange(o.payment_due_date,ws,we):orderFilter==='overdue'?o.payment_due_date&&o.payment_due_date<day:true);return section('Payments & outstanding',`<div class="filters">${[['pending','Pending'],['today','Due today'],['week','This week'],['overdue','Overdue'],['all','All']].map(([k,l])=>action(l,`data-filter="${k}"`,orderFilter===k)).join('')}</div>`+table(['Client / order','Total','Paid','Balance','Due','Status',''],rows.map(o=>[`<b>${esc(customer(o))}</b><small>${esc(o.reference)}</small>`,moneyCell(o.amount),moneyCell(received(data,o.id)),moneyCell(balance(data,o)),date(o.payment_due_date),badge(paymentStatus(data,o)),action(balance(data,o)>0?'Record payment':'Open',balance(data,o)>0?`data-payment="${o.id}"`:`data-detail="${o.id}"`)])));}
function field([key,label,type,required=false,defaultValue],record={}){
 const value=record[key]??(typeof defaultValue==='function'?defaultValue():defaultValue??'');let input;
 if(['client','order','piece','product','person'].includes(type)){const options=type==='piece'?data.studio_pieces.map(p=>[p.id,`${p.collection||'Studio'} · ${p.name}`]):type==='product'?data.order_items.map(i=>[i.id,productLabel(i.id)]):type==='person'?people.map(p=>[p.user_id,p.name]):type==='client'?data.customers.map(c=>[c.id,c.name]):sortOrders(data.orders).map(o=>[o.id,`${o.reference} · ${customer(o)}`]);input=`<select name="${key}" ${required?'required':''}><option value="">${type==='client'?'Select client':required?'Select order':'Stock / general'}</option>${options.map(([id,name])=>`<option value="${id}" ${id===value?'selected':''}>${esc(name)}</option>`).join('')}</select>`;}
 else if(Array.isArray(type))input=`<select name="${key}" ${required?'required':''}>${type.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${v==='Bank transfer'?'Bank Transfer':esc(v)}</option>`).join('')}</select>`;
 else if(type==='textarea')input=`<textarea name="${key}" rows="3" ${required?'required':''}>${esc(value)}</textarea>`;
 else input=`<input name="${key}" type="${type==='staff'?'text':type}" ${type==='staff'?'list="staff-names"':''} value="${esc(value)}" ${type==='number'?'min="0" step="0.01"':''} ${required?'required':''}>`;
 return `<label class="${type==='textarea'?'wide':''}"><span class="field-label">${esc(label.replace(/\s*\(optional\)/ig,''))}${required?'':'<span class="optional-tag">Optional</span>'}</span>${input}</label>`;
}
function tagOptionalFields(root){root.querySelectorAll('label').forEach(label=>{const control=label.querySelector('input,select,textarea');if(!control||control.required||control.disabled||control.readOnly||control.type==='checkbox'||control.type==='radio'||label.querySelector('.optional-tag'))return;for(const node of label.childNodes)if(node.nodeType===3)node.textContent=node.textContent.replace(/\s*\(optional\)/ig,'');const tag=document.createElement('span');tag.className='optional-tag';tag.textContent='Optional';let name=label.querySelector('.field-label');if(!name){name=document.createElement('span');name.className='field-label';const texts=[...label.childNodes].filter(n=>n.nodeType===3);texts.forEach(n=>name.append(n));label.prepend(name);}name.append(tag);});}
function openModal(title,body,buttons='',onSubmit){
 if(dialog.open)dialog.close();dialog.classList.remove('invoice-dialog');dialog.innerHTML=`<form id="record-form"><div class="modal-heading"><h2>${esc(title)}</h2><button type="button" id="close" aria-label="Close">×</button></div><div class="modal-scroll">${body}<p class="form-error" role="alert"></p></div><div class="modal-actions">${buttons}${action('Close','type="button" id="cancel"')}${onSubmit?'<button type="submit" class="primary">Save</button>':''}</div></form>`;
 document.querySelector('#close').onclick=()=>dialog.close();document.querySelector('#cancel').onclick=()=>dialog.close();
 const form=document.querySelector('#record-form');form.onsubmit=async e=>{e.preventDefault();if(!onSubmit)return;const button=form.querySelector('[type=submit]');button.disabled=true;let saved;try{saved=await onSubmit(new FormData(form),form);}catch(err){form.querySelector('.form-error').textContent=err.message;button.disabled=false;return;}dialog.close();try{await reloadData();render();notify('Saved successfully');if(saved?.invoiceOrderId)invoiceReady(saved.invoiceOrderId);if(saved?.paymentOrderId)paymentForm('order',saved.paymentOrderId);if(saved?.paymentDetailsOrderId)orderDetail(saved.paymentDetailsOrderId);}catch{notify('Saved. Refresh to see the latest balances.');}};tagOptionalFields(form);dialog.showModal();lockModalPage();wireDelete(form);return form;
}
async function reloadData(){const result=await workspace();profile=result.profile;overview=result.home||{};people=result.people||[];members=result.members||[];data=Object.fromEntries(tables.map(key=>[key,result[key]||[]]));await loadMoneySummary();await loadHomeMetrics();}
function edit(m,record={}){
 if(m==='expenses'&&!record.id){quickExpenses();return;}
 if(m==='influencer_marketing'){marketingForm(record);return;}
 if(m==='orders'){orderForm(record);return;}
 const definition={...definitions[m],fields:definitions[m].fields.filter(([k])=>!(m==='purchases'&&record.id&&k==='status')&&!(m==='jobs'&&k==='payment_status'&&!can('expenses'))&&!(k==='assigned_user_id'&&!can('owner'))&&!(k==='additional_cost'&&!can('expenses'))).map(f=>m==='expenses'&&f[0]==='category'&&record.category!=='Salary'?[f[0],f[1],f[2].filter(c=>c!=='Salary'),f[3],f[4]]:f)},newId=crypto.randomUUID();let extra='';
 if(m==='salary_profiles')extra='<p class="helper">Save once. Record each payment with its actual date; monthly totals update automatically.</p>';
 if(m==='purchases'&&!record.id)extra=`<div id="partial-purchase" hidden><div class="form-grid">${field(['paid_now','Amount paid now (₹)','number',true,0])}${field(['paid_date','Payment date','date',true,today])}</div></div>`;
 if(m==='salaries')extra='<p class="helper">Salary is the amount owed for this pay period, not necessarily a monthly rate. Record actual payments and advances after saving. The period-start month gets the salary cost.</p>';
 if(m==='expenses')extra=`<label>Manual category<input name="manual_category" maxlength="80" placeholder="Type category" value="${!expenseCategories.includes(record.category)&&record.category!=='Salary'?esc(record.category||''):''}"></label>`+'<p class="helper">Record business entries manually. Enter each cost once, here or in Purchases / Salaries.</p>';
 const form=openModal(`${record.id?'Edit':'New'} ${definition.singular}`,`<div class="form-grid">${definition.fields.map(f=>field(f,record)).join('')}</div>${extra}<datalist id="staff-names">${[...new Set(data.salaries.map(s=>s.staff_name))].map(name=>`<option value="${esc(name)}">`).join('')}</datalist>`,deleteButton(m,record.id),async f=>{
  const body={};definition.fields.forEach(([key,,type])=>body[key]=type==='number'?n(f.get(key)):(f.get(key)||null));
  if(m==='expenses'&&body.category==='Manual'){body.category=String(f.get('manual_category')||'').trim();if(!body.category)throw Error('Enter a manual category.');}
  if(m==='purchases'&&!record.id&&body.status==='Part paid'){body.paid_now=n(f.get('paid_now'));body.paid_date=f.get('paid_date');}
  if(m==='jobs'&&!!body.order_item_id===!!body.studio_piece_id)throw Error('Choose one client product OR one studio piece.');
  if(m==='salaries'&&body.period_end<body.period_start)throw Error('Period end must be on or after period start.');
  if(!record.id)body.id=newId;
  const saved=await save(m,body,record.id);if(!saved?.length)throw Error('No record was saved. Please refresh and try again.');
 });
 if(m==='expenses'){const select=form.elements.category,custom=form.elements.manual_category;const unknown=record.category&&!expenseCategories.includes(record.category)&&record.category!=='Salary';if(unknown)select.value='Manual';if(record.category==='Salary'){select.insertAdjacentHTML('afterbegin','<option value="Salary">Salary (existing)</option>');select.value='Salary';}const refresh=()=>{custom.parentElement.hidden=select.value!=='Manual';custom.required=select.value==='Manual';};select.onchange=refresh;refresh();}
 if(m==='purchases'&&!record.id){const refresh=()=>{form.querySelector('#partial-purchase').hidden=form.elements.status.value!=='Part paid';form.elements.paid_now.required=form.elements.status.value==='Part paid';form.elements.paid_date.required=form.elements.status.value==='Part paid';};form.elements.status.onchange=refresh;refresh();}
 if(m==='salary_profiles'){if(!record.id){form.elements.frequency.value='Weekly';form.elements.payment_day.value='Saturday';}form.elements.frequency.onchange=()=>{form.elements.payment_day.value=form.elements.frequency.value==='Weekly'?'Saturday':'';};}
 if(m==='salaries'){
  const calculateEnd=()=>{const start=form.elements.period_start.value;if(!start)return;form.elements.period_end.value=form.elements.frequency.value==='Weekly'?addDays(start,6):monthRange(start.slice(0,7))[1];};
  if(!record.id)calculateEnd();form.elements.frequency.onchange=()=>{if(!record.id)form.elements.period_start.value=form.elements.frequency.value==='Weekly'?weekRange(today())[0]:today().slice(0,7)+'-01';calculateEnd();};form.elements.period_start.onchange=calculateEnd;
  form.elements.staff_name.onchange=()=>{if(record.id)return;const previous=data.salaries.find(s=>s.staff_name===form.elements.staff_name.value);if(previous){form.elements.salary.value=previous.salary;form.elements.frequency.value=previous.frequency;calculateEnd();}};
 }
}
function paymentForm(type,id){
 const newId=crypto.randomUUID(),isOrder=type==='order',item=isOrder?order(id):data.salaries.find(s=>s.id===id),remaining=isOrder?balance(data,item):salaryBalance(data,item);
 openModal(isOrder?'Record client payment':'Record salary payment',`<p>${esc(isOrder?orderLabel(id):item.staff_name)} · Remaining ${money(remaining)}</p><div class="form-grid">${field(['amount','Amount (₹)','number',true,remaining])}${field(['payment_date','Payment date','date',true,today])}${field(['kind','Type',isOrder?['Payment','Advance']:['Salary','Advance'],true])}${field(['payment_mode','Payment mode',modes,true])}${field(['notes','Notes','textarea'])}</div>`,'',async f=>{const amount=n(f.get('amount'));if(amount<=0)throw Error('Enter an amount greater than zero.');if(amount>remaining)throw Error('Amount exceeds the remaining balance.');await save(isOrder?'order_payments':'salary_payments',{id:newId,[isOrder?'order_id':'salary_id']:id,amount,payment_date:f.get('payment_date'),kind:f.get('kind'),payment_mode:f.get('payment_mode'),notes:f.get('notes')||null});});
}
function paymentHistory(rows,type){return `<div class="money-entries">${rows.sort((a,b)=>b.payment_date.localeCompare(a.payment_date)).map(p=>entryCard(date(p.payment_date),`<strong>${money(p.amount)}</strong>`,`<p class="entry-subtitle">${esc(p.kind)} · ${esc(p.payment_mode)}</p>`,(p.voided?badge('Voided'):action('Void',`type="button" data-void="${p.id}" data-ledger="${type}"`))+deleteButton(type,p.id))).join('')||'<p class="home-empty">No payments recorded.</p>'}</div>`;}
function wireVoid(){dialog.querySelectorAll('[data-void]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await save(b.dataset.ledger,{voided:true},b.dataset.void);await reloadData();dialog.close();render();notify('Payment voided; balances and summaries updated.');}catch(err){dialog.querySelector('.form-error').textContent=err.message;b.disabled=false;}});}
function orderDetail(id){const o=order(id);openModal(`Order ${o.reference}`,`<p>${esc(customer(o))} · ${date(o.order_date)}</p>${simpleSummary([['Delivery',date(o.due_date)],['Fitting',date(o.fitting_date)],...(o.trials?[['Trials',o.trials]]:[]),['Overall stage',o.status],['Assigned to',o.assigned_to||'—'],...(can('payments')?[['Order value',money(o.amount)],['Advance paid',money(sum(paymentsFor(data,id).filter(p=>p.kind==='Advance')))],['Paid',money(received(data,id))],['Balance',money(balance(data,o))]]:[])])}<h3>Products</h3>${itemsFor(id).map(i=>`<article class="product-detail"><b>${esc(i.name)} · ${esc(i.quantity)} ${can('payments')?' · '+money(n(i.price)*n(i.quantity)):''}</b> ${badge(i.status)}<p>${esc(i.description||'')}</p><small>${esc(i.fabric||'')} · Delivery ${date(i.due_date||o.due_date)}</small><p class="detail-notes">${esc(i.notes||'')}</p></article>`).join('')}<div class="detail-actions">${can('payments')&&can('clients')&&o.status!=='Cancelled'?action('Generate Invoice','type="button" id="open-invoice"'):''}${can('orders')?action('Edit order','type="button" id="edit-order"')+deleteButton('orders',id):''}${can('payments')&&balance(data,o)>0&&o.status!=='Cancelled'?action('+ Add Payment','type="button" id="pay-order"',true):''}</div>${can('payments')?'<h3>Payment history</h3>'+paymentHistory(data.order_payments.filter(p=>p.order_id===id),'order_payments'):''}<p class="detail-notes">${esc(o.notes||'')}</p>`);document.querySelector('#open-invoice')?.addEventListener('click',()=>openInvoice(id));document.querySelector('#edit-order')?.addEventListener('click',()=>orderForm(o));document.querySelector('#pay-order')?.addEventListener('click',()=>paymentForm('order',id));wireVoid();}
function salaryDetail(id){const s=data.salaries.find(s=>s.id===id);openModal(s.staff_name,`<p>${date(s.period_start)} – ${date(s.period_end)} · ${esc(s.frequency)}</p>${simpleSummary([['Salary',money(s.salary)],['Deduction',money(s.deduction)],['Total paid / advance',money(sum(salaryPayments(data,id)))],['Remaining balance',money(salaryBalance(data,s))]])}<div class="detail-actions">${action('Edit period','type="button" id="edit-salary"')+deleteButton('salaries',id)}${salaryBalance(data,s)>0?action('Record payment / advance','type="button" id="pay-salary"',true):''}</div><h3 class="form-subheading">Payments</h3>${paymentHistory(data.salary_payments.filter(p=>p.salary_id===id),'salary_payments')}<p class="detail-notes">${esc(s.notes||'')}</p>`);document.querySelector('#edit-salary').onclick=()=>edit('salaries',s);document.querySelector('#pay-salary')?.addEventListener('click',()=>paymentForm('salary',id));wireVoid();}
function clientDetail(id){const c=data.customers.find(c=>c.id===id),orders=data.orders.filter(o=>o.customer_id===id);openModal(c.name,`${simpleSummary([['Phone',c.phone||'—'],['Email',c.email||'—'],['Instagram',c.instagram||'—'],['City',c.city||'—'],['Address',c.address||'—'],['Measurement date',date(c.measurement_date)],...(can('payments')?[['Total spent',money(orders.reduce((s,o)=>s+received(data,o.id),0))],['Outstanding',money(orders.reduce((s,o)=>s+balance(data,o),0))]]:[])])}<h3>Measurements</h3><p class="detail-notes">${esc(c.measurements||'Not recorded')}</p><h3>Design / fitting preferences</h3><p class="detail-notes">${esc(c.preferences||'')}</p><h3>Alteration notes</h3><p class="detail-notes">${esc(c.alteration_notes||'')}</p><p class="detail-notes">${esc(c.notes||'')}</p><h3>Current orders</h3>${deliveryRows(orders.filter(activeOrder))}<h3>Past orders</h3>${deliveryRows(orders.filter(o=>!activeOrder(o)))}`,action('Edit client','type="button" id="edit-client"')+deleteButton('customers',id));document.querySelector('#edit-client').onclick=()=>edit('customers',c);bindRecords(dialog);}
const productLabel=id=>{const i=data.order_items.find(i=>i.id===id);return i?`${order(i.order_id)?.reference||'Order'} · ${i.name}`:'—';};
function choosePayment(){const rows=data.orders.filter(o=>o.status!=='Cancelled'&&balance(data,o)>0);openModal('Record payment',table(['Order / client','Balance',''],rows.map(o=>[esc(orderLabel(o.id)),moneyCell(balance(data,o)),action('Select',`type="button" data-payment="${o.id}"`)])));bindRecords(dialog);}
function productFields(item,index,finance,simple=false){const core=[['name','Product / Outfit name','text',true],...(finance?[['quantity','Quantity','number',true,1],['price','Price per piece (₹)','number',true,0]]:[]),['status','Production stage',stages.filter(s=>!simple||s!=='Cancelled'),true,'New Order'],['fabric','Fabric','text'],...(simple?[['description','Design notes','textarea']]:[])];return `<fieldset class="product-form ${simple?'simple-product':''}" data-product="${esc(item.id||crypto.randomUUID())}"><legend>Outfit / product ${index+1}</legend><div class="form-grid">${core.map(f=>field(f,item)).join('').replaceAll('rows="3"','rows="2"')}</div>${finance?action('Remove product','type="button" data-remove-product'):''}</fieldset>`;}
function orderForm(record={}){
 const finance=can('payments'),existing=!!record.id,id=record.id||crypto.randomUUID(),items=existing?itemsFor(id):[{id:crypto.randomUUID(),quantity:1,price:0,status:'New Order'}];
 const orderFields=!existing?[['customer_id','Select Client','client',true],['reference','Order number','text',true],['order_date','Order date','date',true],['due_date','Delivery date','date',true],['trials','Trials','text']]:finance?[['reference','Order number','text',true],['customer_id','Client','client',true],['order_date','Order date','date',true],['due_date','Delivery date','date'],['trials','Trials','text'],['overall_state','Order state',['Active','Cancelled'],true,'Active'],['assigned_to','Assigned to','staff']]:[['due_date','Delivery date','date'],['trials','Trials','text'],['assigned_to','Assigned to','staff']];
 const clientButton=finance&&can('clients')?action('+ New Client','type="button" id="quick-client-open"'):'';
 const details=existing?`<h3 class="order-section-title">Order details</h3><div class="form-grid">${orderFields.filter(([k])=>!['overall_state','assigned_to','notes'].includes(k)).map(f=>field(f,record)+(f[0]==='customer_id'?field(['client_phone','WhatsApp number','tel'],{client_phone:data.customers.find(c=>c.id===record.customer_id)?.phone||''}):'')).join('')}</div><details class="order-extra-fields"><summary>More order details</summary><div class="form-grid">${orderFields.filter(([k])=>['overall_state','assigned_to','notes'].includes(k)).map(f=>field(f,{...record,overall_state:record.status==='Cancelled'?'Cancelled':'Active'})).join('')}</div>${clientButton}</details>`:`<h3 class="order-section-title">Client</h3><div class="order-client-row">${field(orderFields[0])}${clientButton}</div><h3 class="order-section-title">Order details</h3><div class="form-grid">${orderFields.slice(1).map(f=>field(f)).join('')}</div>`;
 const form=openModal(existing?'Edit order':'New order',`${details}<h3 class="order-section-title">Products / outfits</h3><div id="products">${items.map((i,j)=>productFields(i,j,finance,!existing)).join('')}</div>${finance?action('+ Add another outfit/product','type="button" id="add-product"'):''}${finance?'<p class="order-total" id="order-total"></p>':''}${finance&&existing?`<h3 class="order-section-title">Payment</h3><div class="edit-order-payments">${simpleSummary([['Advance paid',money(sum(paymentsFor(data,id).filter(p=>p.kind==='Advance')))],['Paid to date',money(received(data,id))],['Balance',money(balance(data,record))]])}${action(balance(data,record)>0?'Save & Add Payment':'Payment details','type="button" id="edit-order-payment-details"')}</div>`:''}${finance&&!existing?`<h3 class="order-section-title">Payment</h3><div class="form-grid">${field(['advance','Advance paid (₹)','number',true,0])}${field(['payment_mode','Payment Mode',['','UPI','Cash']])}<label>Balance amount<output id="order-balance" class="balance-output" aria-live="polite"></output></label></div>`:''}`,deleteButton('orders',record.id),async(f,form)=>{
 const p_order={};orderFields.forEach(([k])=>p_order[k]=f.get(k)||null);if(existing){p_order.notes=record.notes||null;if(finance)p_order.payment_due_date=record.payment_due_date||null;}if(!existing){p_order.id=id;p_order.overall_state='Active';p_order.advance_date=p_order.order_date;p_order.payment_mode=f.get('payment_mode')||null;}
 const p_items=[...form.querySelectorAll('[data-product]')].map((node,position)=>{const original=items.find(i=>i.id===node.dataset.product);const row={id:node.dataset.product,position,...(existing?{due_date:original?.due_date||null,notes:original?.notes||null,description:original?.description||null}:{})};node.querySelectorAll('[name]').forEach(input=>row[input.name]=['quantity','price'].includes(input.name)?n(input.value):input.value||null);if(!finance)delete row.position;return row;});
 if(!existing&&n(f.get('advance'))>productTotal(p_items))throw Error('Advance cannot exceed the total order value.');
 if(p_items.length===0)throw Error('Add at least one product.');if(p_items.some(i=>finance&&i.quantity<=0))throw Error('Product quantity must be greater than zero.');
 if(existing&&can('clients')){const clientId=f.get('customer_id')||record.customer_id,client=data.customers.find(c=>c.id===clientId),phone=String(f.get('client_phone')||'').trim()||null;if(client&&phone!==(client.phone||null))await save('customers',{phone},clientId);}
 const result=await rpc('save_order',{p_order,p_items,p_id:record.id||null,p_advance:finance&&!existing?n(f.get('advance')):0});if(!existing&&can('clients'))return {invoiceOrderId:result.id};if(form.dataset.openPayments==='true')return balance(data,record)>0?{paymentOrderId:id}:{paymentDetailsOrderId:id};
 });
 form.classList.add(existing?'simple-order-editor':'quick-order');
 const total=()=>{const rows=[...form.querySelectorAll('[data-product]')].map(node=>({quantity:node.querySelector('[name=quantity]')?.value,price:node.querySelector('[name=price]')?.value}));const value=productTotal(rows);form.querySelector('#order-total').textContent='Total order value · '+money(value);const paidSummary=form.querySelector('.edit-order-payments .summary div:last-child dd');if(paidSummary)paidSummary.textContent=money(Math.max(0,value-received(data,id)));const remaining=form.querySelector('#order-balance');if(remaining)remaining.textContent=money(Math.max(0,value-n(form.elements.advance.value)));if(form.elements.advance)form.elements.advance.max=String(value);};
 const wireProducts=()=>{const cards=[...form.querySelectorAll('[data-product]')];cards.forEach((card,index)=>card.querySelector('legend').textContent=(existing?'Product ':'Outfit / product ')+(index+1));form.querySelectorAll('[data-remove-product]').forEach(b=>{b.hidden=!existing&&cards.length===1;b.onclick=()=>{if(form.querySelectorAll('[data-product]').length===1){notify('Keep at least one product.');return;}b.closest('fieldset').remove();wireProducts();};});if(finance)total();};
 form.querySelector('#add-product')?.addEventListener('click',()=>{form.querySelector('#products').insertAdjacentHTML('beforeend',productFields({},form.querySelectorAll('[data-product]').length,true,!existing));wireProducts();});
 if(finance)form.addEventListener('input',total);if(!existing)form.querySelector('[type=submit]').textContent='Create Order';wireProducts();
 const phoneInput=form.querySelector('[name=client_phone]');if(phoneInput&&!can('clients'))phoneInput.readOnly=true;form.querySelector('[name=customer_id]')?.addEventListener('change',()=>{if(phoneInput)phoneInput.value=data.customers.find(c=>c.id===form.elements.customer_id.value)?.phone||'';});form.querySelector('#edit-order-payment-details')?.addEventListener('click',()=>{form.dataset.openPayments='true';form.requestSubmit();});
 form.querySelector('#quick-client-open')?.addEventListener('click',()=>quickClient(form));
}
function quickClient(orderForm){let popup=document.querySelector('#quick-client');if(!popup){popup=document.createElement('dialog');popup.id='quick-client';popup.addEventListener('close',unlockModalPage);document.body.append(popup);}const id=crypto.randomUUID();popup.innerHTML=`<form><div class="modal-heading"><h2>New client</h2><button type="button" aria-label="Close new client" data-client-cancel>×</button></div><div class="quick-client-scroll"><div class="form-grid">${definitions.customers.fields.filter(([k])=>['name','phone','email','instagram','address'].includes(k)).map(f=>field(f)).join('')}</div><p class="form-error" role="alert"></p></div><div class="modal-actions"><button type="button" data-client-cancel>Cancel</button><button type="submit" class="primary">Save Client</button></div></form>`;popup.querySelectorAll('[data-client-cancel]').forEach(b=>b.onclick=()=>popup.close());popup.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),body={id};for(const [k,v]of f)body[k]=v||null;const button=e.currentTarget.querySelector('[type=submit]');button.disabled=true;try{await save('customers',body);if(!data.customers.some(c=>c.id===id))data.customers.push(body);const select=orderForm.querySelector('[name=customer_id]');if(select){if(![...select.options].some(o=>o.value===id))select.add(new Option(body.name,id));select.value=id;select.dispatchEvent(new Event('change',{bubbles:true}));}popup.close();notify('Client added. Continue your order.');}catch(err){popup.querySelector('.form-error').textContent=err.message;button.disabled=false;}};tagOptionalFields(popup);popup.showModal();lockModalPage();}
let agendaDate=today();
function calendarPage(){const [start,end]=weekRange(agendaDate),entries=[];const add=(day,title,kind,time)=>{if(inRange(day,start,end))entries.push({day,title,kind,time:time||''});};data.orders.filter(activeOrder).forEach(o=>{add(o.due_date,orderLabel(o.id),'Delivery');add(o.fitting_date,orderLabel(o.id),'Client fitting');itemsFor(o.id).filter(i=>activeOrder(i)&&i.due_date&&i.due_date!==o.due_date).forEach(i=>add(i.due_date,`${o.reference} · ${i.name}`,'Product delivery'));});data.studio_pieces.filter(activeOrder).forEach(p=>{add(p.due_date,p.name,'Studio piece');add(p.shoot_date,p.name,'Shoot');});data.jobs.filter(j=>!['Returned','Cancelled'].includes(j.status)).forEach(j=>add(j.due_date,`${j.karigar} · ${j.work}`,'Karigar deadline'));data.tasks.filter(t=>!t.done).forEach(t=>add(t.task_date,t.title,t.category,t.task_time));data.events.forEach(e=>add(e.event_date,e.title,e.category,e.event_time));entries.sort((a,b)=>a.day.localeCompare(b.day)||a.time.localeCompare(b.time));return section('Studio calendar',`<div class="table-tools"><label>Week of<input type="date" id="agenda-date" value="${agendaDate}"></label>${can('calendar')?action('+ Event','data-add="events"'):''}</div><p class="helper">${date(start)} – ${date(end)} · Deliveries, fittings, shoots, pickups, tasks and karigar deadlines.</p>`+table(['Date / time','What’s happening','Type'],entries.map(e=>[`${date(e.day)}<small>${esc(e.time.slice(0,5))}</small>`,esc(e.title),badge(e.kind)]))+ (can('calendar')&&data.events.length?`<h3>Manual events</h3>${table(['Event','Date',''],data.events.map(e=>[esc(e.title),date(e.event_date),action('Edit',`data-edit="${e.id}" data-module="events"`)]))}`:''));}
function memberPage(){return section('Team access',`<p class="helper">Muskan controls access. Home and business totals are private unless explicitly granted. Create a confirmed login in Supabase Authentication before adding access here.</p>${action('+ Team access','id="add-member"',true)}${table(['Name / email','Role','Access',''],members.map(m=>[`<b>${esc(m.name||'Team member')}</b><small>${esc(m.email)}</small>`,esc(m.role),esc(m.role==='owner'?'Everything':m.permissions.join(', ')),m.role==='owner'?badge('Owner'):action('Edit access',`data-member="${m.user_id}"`)]))}`);}
function memberForm(member={}){const permissionList=['marketing','home','orders','clients','studio','production','tasks','calendar','payments','expenses','purchases','salaries'];const labels={marketing:'Influencer Marketing',home:'Home / business overview (explicit grant)',orders:'Orders / production stages',clients:'Clients / measurements',studio:'Studio pieces',production:'Karigar jobs',tasks:'Assigned tasks',calendar:'Calendar',payments:'Client payments / individual balances',expenses:'Expense entries',purchases:'Purchases',salaries:'Salary records'};const form=openModal('Team access',`<div class="form-grid">${field(['email','Confirmed login email','email',true],member)}${field(['name','Display name','text'],member)}${field(['role','Role',['production','team','accounts'],true,'team'],member)}</div><h3>Allowed sections</h3><div class="permissions">${permissionList.map(p=>`<label><input type="checkbox" name="permission" value="${p}" ${member.permissions?.includes(p)?'checked':''}>${esc(labels[p])}</label>`).join('')}</div><p class="helper">Orders plus Payments permits creating orders and changing their prices. Team members see only tasks they created or that are assigned to them. Accounts roles do not get business totals.</p>`,member.user_id?action('Remove access','type="button" id="remove-member"'):'',async f=>{await rpc('manage_member',{p_email:f.get('email'),p_role:f.get('role'),p_permissions:f.getAll('permission'),p_name:f.get('name')||null});});const apply=()=>{form.querySelectorAll('[name=permission]').forEach(c=>c.checked=rolePermissions[form.elements.role.value].includes(c.value));};if(!member.user_id)apply();form.elements.role.onchange=apply;form.querySelector('#remove-member')?.addEventListener('click',async()=>{try{await rpc('remove_member',{p_user_id:member.user_id});dialog.close();await reloadData();render();notify('Team access removed.');}catch(err){form.querySelector('.form-error').textContent=err.message;}});}
async function loadMoneySummary(){monthlyMoney=can('home')?await rpc('month_money',{p_month:selectedMoneyMonth}):null;}
function cashSummary(){if(!monthlyMoney)return '';return `<div class="money-overview-grid">`+section('Money in',`<div class="money-in-summary">${[['Sales',monthlyMoney.sales],['Collected',monthlyMoney.collected],['Client outstanding',monthlyMoney.outstanding]].map(([label,value])=>`<div><span>${label}</span><strong>${money(value)}</strong></div>`).join('')}</div><p class="money-note">Outstanding at month end · Collections by payment date</p>`)+section('Cash flow',`<div class="cash-out-grid">${[['Collected',monthlyMoney.collected],['Total Expenses',monthlyMoney.total_out]].map(([label,value])=>`<div><span>${label}</span><strong>${money(value)}</strong></div>`).join('')}</div><div class="cash-net"><span>Net Cash Flow<small>Collected − Total Expenses</small></span><strong>${money(monthlyMoney.net)}</strong></div>`)+`</div>`;}
function monthSelector(){return `<div class="money-month"><button data-money-month="-1" aria-label="Previous month">‹</button><h2>${monthLabel(selectedMoneyMonth)}</h2><button data-money-month="1" aria-label="Next month">›</button></div>`;}
function moneyPage(){return `<div class="mobile-money">${monthSelector()}${cashSummary()}${moneyEntries()}</div>`;}
function expensesPage(){const tabs=[['expenses','Expenses'],['salaries','Salaries'],['purchases','Purchases']].filter(([key])=>can(permissions[key]));return `<div class="expense-page daily-expense-page"><div class="daily-expense-tabs" role="group" aria-label="Expense sections">${tabs.map(([key,label])=>action(label,`data-tab="${key}" aria-pressed="${view===key}"`,view===key)).join('')}</div>${expenseMonthSelector()}${expenseSheet()}${expenseMonthlyTotals()}</div>`;}
function expenseMonthSelector(){return `<div class="expense-month-selector"><button type="button" data-expense-month="-1" aria-label="Previous expense month">‹</button><label><span class="sr-only">Expense month</span><input type="month" id="expense-month" value="${selectedExpenseMonth}" aria-label="Expense month"></label><button type="button" data-expense-month="1" aria-label="Next expense month">›</button></div>`;}
function expenseMonthlyTotals(){const totals=cashMonth(data,selectedExpenseMonth),rows=[['expenses','Expenses',totals.other_expenses],['salaries','Salaries',totals.salaries],['purchases','Purchases',totals.purchases]].filter(([key])=>can(permissions[key]));return `<section class="expense-month-totals" aria-label="Monthly expense totals"><h3>${esc(monthLabel(selectedExpenseMonth))} · Paid totals</h3>${rows.map(([,label,value])=>`<div><span>${label}</span><strong>${money(value)}</strong></div>`).join('')}<div class="expense-month-total"><span>Total Expenses</span><strong>${money(rows.reduce((total,[,,value])=>total+value,0))}</strong></div><p>Based on actual payments this month. Pending amounts are excluded.</p></section>`;}
function expenseSheet(){const [monthStart,monthEnd]=monthRange(selectedExpenseMonth);sheetRows=expenseRows(data,view,selectedExpenseMonth).filter(r=>r.date?inRange(r.date,monthStart,monthEnd):selectedExpenseMonth===today().slice(0,7));const rows=filterExpenseRows(sheetRows,expenseFilters).filter(r=>!expenseFilters.search||[r.name,r.category,r.vendor,r.paid_by,r.mode,r.record.notes].some(v=>String(v||'').toLowerCase().includes(expenseFilters.search.toLowerCase()))),pages=Math.max(1,Math.ceil(rows.length/50));expenseFilters.page=Math.min(expenseFilters.page,pages-1);const page=rows.slice(expenseFilters.page*50,expenseFilters.page*50+50),categories=[...new Set(sheetRows.map(r=>r.category))].sort(),label=view==='purchases'?'Purchase':view==='salaries'?'Salary':'Expense',title=view==='purchases'?'Purchases':view==='salaries'?'Salaries':'Expenses';return `<section class="daily-expense-tracker" aria-label="${title} tracker"><div class="daily-expense-heading"><h2>${title}</h2>${action('+ Add '+label,'type="button" id="sheet-add"',true)}</div><label class="daily-expense-search"><span aria-hidden="true">⌕</span><input id="expense-search" type="search" placeholder="Search ${title.toLowerCase()}…" aria-label="Search ${title.toLowerCase()}" value="${esc(expenseFilters.search||'')}"></label><div class="daily-expense-filter-line"><div class="expense-status-tabs" role="group" aria-label="Payment status">${[['','All'],['Paid','Paid'],['Pending','Pending'],['Part paid','Part Paid']].map(([k,l])=>action(l,`data-expense-status="${k}" aria-pressed="${expenseFilters.status===k}"`,expenseFilters.status===k)).join('')}</div><details class="expense-filter-panel" ${expenseFilterOpen?'open':''}><summary>More filters${[expenseFilters.from,expenseFilters.to,expenseFilters.category].some(Boolean)?' · Active':''}</summary><div class="expense-filters"><label>From<input type="date" data-sheet-filter="from" value="${esc(expenseFilters.from)}"></label><label>To<input type="date" data-sheet-filter="to" value="${esc(expenseFilters.to)}"></label><label>${view==='salaries'?'Role':'Category'}<select data-sheet-filter="category"><option value="">All</option>${categories.map(c=>`<option value="${esc(c)}" ${expenseFilters.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Sort<select data-sheet-filter="sort">${[['date','Date'],['amount','Amount'],['name','Name']].map(([k,l])=>`<option value="${k}" ${expenseFilters.sort===k?'selected':''}>${l}</option>`).join('')}</select></label><label>Status<select data-sheet-filter="status">${[['','All active'],['Paid','Paid'],['Pending','Pending'],['Part paid','Part Paid'],['Voided','Voided']].map(([v,l])=>`<option value="${v}" ${expenseFilters.status===v?'selected':''}>${l}</option>`).join('')}</select></label><button type="button" id="sheet-clear">Reset</button></div></details></div><div class="daily-expense-list" role="list" aria-label="${title} entries">${page.map(r=>{const expense=r.table==='expenses'&&r.record.category!=='Salary',name=expense?r.category:r.name,description=expense?(r.name===r.category?'':r.name):view==='purchases'?[r.category,r.vendor].filter(Boolean).join(' · '):[r.category==='—'?'':r.category,r.period].filter(Boolean).join(' · ');return `<div role="listitem"><button type="button" class="daily-expense-row" data-sheet-row="${esc(r.id)}" aria-label="Manage ${esc(r.name)}"><time ${r.date?`datetime="${esc(r.date)}"`:''}>${r.date?new Date(r.date+'T12:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short'}):'—'}${r.date?`<small>${r.date.slice(0,4)}</small>`:''}</time><span class="daily-expense-description"><b>${esc(name)}</b>${description?`<small>${esc(description)}</small>`:''}</span><span class="daily-expense-amount"><strong>${money(r.amount)}</strong><small class="daily-status ${r.status==='Paid'?'is-paid':r.status==='Pending'?'is-pending':'is-partial'}">${esc(r.status==='Part paid'?'Part Paid':r.status)}</small></span><span class="daily-expense-chevron" aria-hidden="true">›</span></button></div>`;}).join('')||`<div class="daily-expense-empty"><p>${expenseFilters.search||expenseFilters.status||expenseFilters.from||expenseFilters.to||expenseFilters.category?'No entries match your filters.':'No '+title.toLowerCase()+' yet.'}</p><small>${rows.length?'':'Use + Add '+label+' to get started.'}</small></div>`}</div><div class="daily-expense-foot"><span>${rows.length} ${rows.length===1?'entry':'entries'}</span>${pages>1?`<div class="expense-pagination"><button type="button" data-sheet-page="-1" ${expenseFilters.page===0?'disabled':''}>Previous</button><span>${expenseFilters.page+1} / ${pages}</span><button type="button" data-sheet-page="1" ${expenseFilters.page===pages-1?'disabled':''}>Next</button></div>`:''}</div></section>`;}
function wireExpenseSheet(){if(group!=='spending')return;const changeExpenseMonth=month=>{if(!/^\d{4}-\d{2}$/.test(month))return;selectedExpenseMonth=month;expenseFilters.from='';expenseFilters.to='';expenseFilters.page=0;render();};document.querySelectorAll('[data-expense-month]').forEach(b=>b.onclick=()=>changeExpenseMonth(shiftMonth(selectedExpenseMonth,Number(b.dataset.expenseMonth))));document.querySelector('#expense-month')?.addEventListener('change',e=>changeExpenseMonth(e.target.value));document.querySelectorAll('[data-expense-status]').forEach(b=>b.onclick=()=>{expenseFilters.status=b.dataset.expenseStatus;expenseFilters.page=0;render();});document.querySelector('#expense-search')?.addEventListener('input',e=>{expenseFilters.search=e.target.value;expenseFilters.page=0;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const value=expenseFilters.search;render();const input=document.querySelector('#expense-search');if(input){input.focus({preventScroll:true});input.setSelectionRange(value.length,value.length);}},160);});const filters=document.querySelector('.expense-filter-panel');if(filters)filters.ontoggle=()=>expenseFilterOpen=filters.open;document.querySelector('#sheet-add')?.addEventListener('click',()=>view==='salaries'?addSheetSalary():edit(view));document.querySelectorAll('[data-sheet-filter]').forEach(input=>input.onchange=()=>{expenseFilters[input.dataset.sheetFilter]=input.value;expenseFilters.page=0;render();});document.querySelector('#sheet-clear')?.addEventListener('click',()=>{expenseFilters={from:'',to:'',category:'',status:'',sort:'date',direction:-1,page:0,search:''};render();});document.querySelectorAll('[data-sheet-sort]').forEach(b=>b.onclick=()=>{expenseFilters.direction=expenseFilters.sort===b.dataset.sheetSort?-expenseFilters.direction:1;expenseFilters.sort=b.dataset.sheetSort;expenseFilters.page=0;render();});document.querySelectorAll('[data-sheet-page]').forEach(b=>b.onclick=()=>{expenseFilters.page+=Number(b.dataset.sheetPage);render();});document.querySelectorAll('[data-sheet-row]').forEach(b=>b.onclick=()=>manageExpenseRow(sheetRows.find(r=>r.id===b.dataset.sheetRow)));}
function addSheetSalary(){const profiles=data.salary_profiles.filter(p=>p.active!==false);const form=openModal('Add Salary',`<p class="helper">Choose a saved salary profile, then record the actual payment date.</p><label>Person<select name="profile_id" required><option value="">Select person</option>${profiles.map(p=>`<option value="${esc(p.id)}">${esc(p.staff_name)} · ${esc(p.frequency)}</option>`).join('')}</select></label>`,action('+ New salary profile','type="button" id="sheet-new-profile"')+action('Record payment','type="button" id="sheet-record-salary"',true));form.querySelector('#sheet-new-profile').onclick=()=>edit('salary_profiles');form.querySelector('#sheet-record-salary').onclick=()=>{if(form.reportValidity())profilePayment(form.elements.profile_id.value);};}
function manageExpenseRow(row){if(!row)return;const pending=row.table==='salary_profiles',voided=row.status==='Voided',purchase=row.table==='purchases';const buttons=action(pending?'Edit profile':'Edit','type="button" id="sheet-edit"')+(row.profile&&!pending?action('Edit salary profile','type="button" id="sheet-profile"'):'')+(pending&&!voided?action('Record Paid','type="button" id="sheet-pay"',true):purchase&&!voided&&purchaseBalance(data,row.record)>0?action('Mark as Paid / Add payment','type="button" id="sheet-pay"',true):'')+(row.table==='expenses'&&!voided&&row.status==='Pending'?action('Mark as Paid','type="button" id="sheet-mark-paid"',true):'')+(pending?action(voided?'Restore profile':'Archive profile','type="button" id="sheet-archive"'):action(voided?'Restore row':'Void row','type="button" id="sheet-void"'));const form=openModal(row.name,detailLines([['Date',row.date?date(row.date):'Not paid'],['Amount',money(row.amount)],['Status',row.status],['Description',row.record.description||row.record.item],['Category / Role',row.category],['Period',row.period],...(purchase?[['Total paid',money(sum(purchasePaymentsFor(data,row.id)))],['Balance',money(purchaseBalance(data,row.record))]]:[])])+(purchase?`<h3>Payment history</h3><div class="payment-mini-list">${purchasePaymentsFor(data,row.id).map(p=>`<p>${date(p.payment_date)} · ${money(p.amount)} ${deleteButton('purchase_payments',p.id)}</p>`).join('')||'<p>No payments recorded.</p>'}</div>`:''),buttons+deleteButton(row.table,row.record.id));form.querySelector('#sheet-mark-paid')?.addEventListener('click',()=>{const confirm=openModal('Mark as Paid',`<p>${esc(row.name)} · ${money(row.amount)}</p><p class="helper">This entry will be included in paid expenses for ${date(row.date)}.</p>`,'',async()=>{await save('expenses',{status:'Paid'},row.id);});confirm.querySelector('[type=submit]').textContent='Mark as Paid';});form.querySelector('#sheet-edit').onclick=()=>row.table==='salary_payouts'?editSheetSalary(row):edit(row.table,row.record);form.querySelector('#sheet-profile')?.addEventListener('click',()=>edit('salary_profiles',row.profile));form.querySelector('#sheet-pay')?.addEventListener('click',()=>pending?profilePayment(row.profile.id):purchasePayment(row.id));form.querySelector('#sheet-archive')?.addEventListener('click',()=>{openModal(voided?'Restore salary profile':'Archive salary profile',`<p>${esc(row.name)}</p><p class="helper">${voided?'Make this profile available for future payments again.':'Hide this pending profile. Existing recorded payments and totals are retained.'}</p>`,'',async()=>{await save('salary_profiles',{active:voided},row.profile.id);});});form.querySelector('#sheet-void')?.addEventListener('click',()=>{openModal(voided?'Restore entry':'Void entry',`<p>${esc(row.name)} · ${money(row.amount)}</p><p class="helper">${voided?'Restore this entry to the totals.':'Remove this entry from expense totals. It remains in the Voided filter and can be restored.'}</p>`,'',async()=>{await rpc('set_expense_void',{p_table:row.table,p_id:row.id,p_voided:!voided});});});}
function editSheetSalary(row){openModal('Edit salary payment',`<p>${esc(row.name)} · ${esc(row.period)}</p><div class="form-grid">${field(['payment_date','Actual payment date','date',true],row.record)}${field(['amount','Amount paid (₹)','number',true],row.record)}${field(['payment_mode','Payment mode',modes,true],row.record)}${field(['notes','Notes','textarea'],row.record)}</div>`,deleteButton(row.table,row.record.id),async f=>{if(n(f.get('amount'))<=0)throw Error('Enter a positive payment.');await save('salary_payouts',{payment_date:f.get('payment_date'),amount:n(f.get('amount')),payment_mode:f.get('payment_mode'),notes:f.get('notes')||null},row.id);});}

function entryCard(title,meta,body,actions=''){return `<article class="money-entry"><div class="money-entry-heading"><h3>${esc(title)}</h3>${meta}</div>${body}${actions?`<div class="money-entry-actions">${actions}</div>`:''}</article>`;}
function detailLines(rows){return `<dl class="entry-lines">${rows.filter(([,v])=>v!==null&&v!==undefined&&v!=='').map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`;}
function moneyEntries(){const [start,end]=monthRange(selectedMoneyMonth),during=day=>inRange(day,start,end);let cards='',title='',add='';
 if(view==='payments'){title='Client payments';const orders=sortOrders(data.orders.filter(o=>paymentMatches(data,o,paymentFilter)&&o.status!=='Cancelled'&&(during(o.order_date)||data.order_payments.some(p=>p.order_id===o.id&&!p.voided&&during(p.payment_date))||(o.order_date<=end&&balance(data,o)>0))));moneyPageCount=Math.max(1,Math.ceil(orders.length/30));moneyPageIndex=Math.min(moneyPageIndex,moneyPageCount-1);cards=orders.slice(moneyPageIndex*30,(moneyPageIndex+1)*30).map(o=>{const rows=paymentsFor(data,o.id).filter(p=>during(p.payment_date));return entryCard(customer(o),badge(paymentStatus(data,o)),`<p class="entry-subtitle">Order #${esc(o.reference)}</p>${detailLines([['Order total',money(o.amount)],['Collected this month',money(sum(rows))],['Paid to date',money(received(data,o.id))],['Balance now',money(balance(data,o))],['Payment due',o.payment_due_date?date(o.payment_due_date):'Not set']])}<details class="client-payment-history"><summary>Payment history · ${data.order_payments.filter(p=>p.order_id===o.id).length} entries</summary><div class="payment-mini-list">${data.order_payments.filter(p=>p.order_id===o.id).sort((a,b)=>b.payment_date.localeCompare(a.payment_date)).map(p=>`<p>${date(p.payment_date)} <b>${money(p.amount)}</b> · ${esc(p.kind)} · ${esc(p.payment_mode)} ${p.voided?badge('Voided'):''}</p>`).join('')||'<p>No payments recorded.</p>'}</div></details>`,action('Open',`data-detail="${o.id}"`)+(balance(data,o)>0?action('+ Add Payment',`data-payment="${o.id}"`,true):''));}).join('');}
 if(view==='expenses'){title='Other Expenses';add=action('+ Expense','data-add="expenses"',true);cards=data.expenses.filter(e=>during(e.expense_date)).sort((a,b)=>b.expense_date.localeCompare(a.expense_date)).map(e=>entryCard(e.description,`<strong>${money(e.amount)}</strong>`,`<p class="entry-subtitle">${date(e.expense_date)} · ${esc(e.category)}</p>${detailLines([['Paid by',e.paid_by],['Mode',e.payment_mode],['Order',e.order_id?orderLabel(e.order_id):null],['Notes',e.notes]])}`,action('Edit',`data-edit="${e.id}" data-module="expenses"`))).join('');}
 if(view==='purchases'){title='Purchases';add=action('+ Purchase','data-add="purchases"',true);cards=data.purchases.filter(p=>during(p.purchase_date)||purchasePaymentsFor(data,p.id).some(r=>during(r.payment_date))).sort((a,b)=>b.purchase_date.localeCompare(a.purchase_date)).map(p=>{const paid=sum(purchasePaymentsFor(data,p.id)),remaining=purchaseBalance(data,p);return entryCard(p.item,`<strong>${money(p.amount)}</strong>`,`<p class="entry-subtitle">${date(p.purchase_date)} · ${esc(p.category)}</p>${detailLines([['Vendor',p.vendor],['Quantity',p.quantity],['Paid this month',money(sum(purchasePaymentsFor(data,p.id).filter(r=>during(r.payment_date))))],['Total paid',money(paid)],['Balance',money(remaining)],['For',p.collection||data.studio_pieces.find(r=>r.id===p.studio_piece_id)?.name||(p.order_id?orderLabel(p.order_id):null)],['Notes',p.notes]])}${badge(remaining===0?'Paid':paid>0?'Part paid':'Unpaid')}${purchasePaymentsFor(data,p.id).filter(r=>during(r.payment_date)).length?`<div class="payment-mini-list">${purchasePaymentsFor(data,p.id).filter(r=>during(r.payment_date)).map(r=>`<p>${date(r.payment_date)} <b>${money(r.amount)}</b> ${action('Void',`data-money-void="${r.id}" data-table="purchase_payments"`)}</p>`).join('')}</div>`:''}`,action('Edit',`data-edit="${p.id}" data-module="purchases"`)+(remaining>0?action('Record payment',`data-purchase-payment="${p.id}"`,true):''));}).join('');}
 if(view==='salaries'){title='Salaries';add=action('+ Salary profile','data-add="salary_profiles"',true);cards=data.salary_profiles.filter(p=>p.active!==false||profilePayments(data,p.id).some(r=>during(r.payment_date))).map(p=>{const rows=profilePayments(data,p.id).filter(r=>during(r.payment_date));return entryCard(p.staff_name,badge(profileStatus(data,p,selectedMoneyMonth)),`<p class="salary-rate">${esc(p.frequency)} · ${money(p.amount)}</p>${p.payment_day?`<p class="entry-subtitle">Payment day: ${esc(p.payment_day)}</p>`:''}${p.frequency==='Weekly'&&selectedMoneyMonth===today().slice(0,7)?'<small>Status for this week</small>':''}${detailLines([['Paid this month',money(sum(rows))],['Payments recorded',rows.length]])}${rows.length?`<div class="payment-mini-list">${rows.sort((a,b)=>b.payment_date.localeCompare(a.payment_date)).map(r=>`<p>${date(r.payment_date)} <b>${money(r.amount)}</b> ${action('Void',`data-money-void="${r.id}" data-table="salary_payouts"`)}</p>`).join('')}</div>`:''}`,action('Edit profile',`data-edit="${p.id}" data-module="salary_profiles"`)+(p.active!==false?action('Record Paid',`data-profile-payment="${p.id}"`,true):''));}).join('');}
 return section(title,`${view==='payments'?`<div class="payment-filter-tabs" role="group" aria-label="Client payment status">${[['all','All'],['unpaid','Unpaid'],['partial','Part paid'],['paid','Paid'],['overdue','Overdue']].map(([k,l])=>action(l,`data-payment-filter="${k}" aria-pressed="${paymentFilter===k}"`,paymentFilter===k)).join('')}</div>`:''}<div class="money-section-action">${add}</div><div class="money-entries">${cards||'<p class="home-empty">No entries for this month.</p>'}</div>${view==='payments'&&moneyPageCount>1?`<div class="record-pagination"><button type="button" data-cash-page="-1" ${moneyPageIndex===0?'disabled':''}>Previous</button><span>${moneyPageIndex+1} / ${moneyPageCount}</span><button type="button" data-cash-page="1" ${moneyPageIndex>=moneyPageCount-1?'disabled':''}>Next</button></div>`:''}`);}
function profilePayment(id){const p=data.salary_profiles.find(p=>p.id===id),stableId=crypto.randomUUID();openModal('Record salary payment',`<p>${esc(p.staff_name)} · ${esc(p.frequency)} · ${money(p.amount)}${p.payment_day?' · '+esc(p.payment_day):''}</p><div class="form-grid">${field(['amount','Amount paid (₹)','number',true,p.amount])}${field(['payment_date','Actual payment date','date',true,today])}${field(['payment_mode','Payment mode',modes,true,'Other'])}${field(['notes','Notes (optional)','textarea'])}</div>`,'',async f=>{if(n(f.get('amount'))<=0)throw Error('Enter a positive payment.');await save('salary_payouts',{id:stableId,profile_id:id,amount:n(f.get('amount')),payment_date:f.get('payment_date'),payment_mode:f.get('payment_mode'),kind:'Salary',notes:f.get('notes')||null});});}
function purchasePayment(id){const p=data.purchases.find(p=>p.id===id),remaining=purchaseBalance(data,p),stableId=crypto.randomUUID();openModal('Record purchase payment',`<p>${esc(p.item)} · Remaining ${money(remaining)}</p><div class="form-grid">${field(['amount','Amount paid (₹)','number',true,remaining])}${field(['payment_date','Actual payment date','date',true,today])}${field(['payment_mode','Payment mode',modes,true,'Other'])}${field(['notes','Notes (optional)','textarea'])}</div>`,'',async f=>{if(n(f.get('amount'))<=0||n(f.get('amount'))>remaining)throw Error('Enter an amount within the remaining balance.');await save('purchase_payments',{id:stableId,purchase_id:id,amount:n(f.get('amount')),payment_date:f.get('payment_date'),payment_mode:f.get('payment_mode'),notes:f.get('notes')||null});});}
function invoiceReady(id){openModal('Order saved','<p>Your invoice is ready to generate from the saved client, products and payments.</p>',action('Generate Invoice','type="button" id="generate-saved-invoice"',true));document.querySelector('#generate-saved-invoice').onclick=()=>openInvoice(id);}
async function openInvoice(id){let snapshot;try{snapshot=await rpc('invoice',{p_order_id:id});}catch(err){notify(err.message);return;}const html=invoiceHTML(snapshot),filename=snapshot.order.invoice_number+'.pdf';openModal('Invoice',`<div class="invoice-preview-viewport">${html}</div><p id="invoice-export-status" class="helper" role="status">Preparing PDF…</p>`,`${action('Download PDF','type="button" id="download-invoice" disabled',true)}${action('Share','type="button" id="share-invoice" disabled')}${action('Send on WhatsApp','type="button" id="whatsapp-invoice" disabled')}`);dialog.classList.add('invoice-dialog');fitInvoicePreview(dialog);const status=dialog.querySelector('#invoice-export-status'),buttons=['download-invoice','share-invoice','whatsapp-invoice'].map(id=>dialog.querySelector('#'+id));let file;const ready=prepareInvoicePDF(html,filename).then(pdf=>{file=pdf;status.textContent='';buttons.forEach(b=>b.disabled=false);}).catch(err=>{status.textContent='PDF could not be prepared: '+err.message;});buttons[0].onclick=()=>downloadInvoicePDF(file);buttons[1].onclick=async()=>{try{status.textContent=await shareInvoicePDF(file,snapshot,false);}catch(err){if(err.name!=='AbortError')status.textContent=err.message;}};buttons[2].onclick=async()=>{try{status.textContent=await shareInvoicePDF(file,snapshot,true);}catch(err){if(err.name!=='AbortError')status.textContent=err.message;}};}

document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&getSession()&&!dialog.open&&!loading)load(true);});
if(getSession())load();else login();

let marketingExpanded=false;
function marketingPage(){const rows=[...data.influencer_marketing].sort((a,b)=>String(b.sent_date||b.created_at).localeCompare(String(a.sent_date||a.created_at))),stats=marketingOverview(rows);return `<section class="panel marketing-overview"><div class="panel-heading"><h2>Studio collaborations</h2>${action('+ Add collaboration','data-add="influencer_marketing"',true)}</div><div class="marketing-stats">${[['Collaborations',stats.total],['Sent out',stats.sent],['Posted / returned',stats.completed]].map(([label,value])=>`<div><strong>${value}</strong><span>${label}</span></div>`).join('')}</div>${action(marketingExpanded?'Show overview ↑':'View detailed list →','id="marketing-expand"')}</section>${marketingExpanded?`<section class="panel"><label class="search"><span>⌕</span><input id="marketing-search" type="search" placeholder="Search collaborations" aria-label="Search collaborations" value="${esc(search)}"></label><div id="marketing-list">${marketingList(rows.filter(r=>marketingMatches(r,search)))}</div></section>`:section('Recent collaborations',marketingList(rows.slice(0,3)))}`;}
function marketingList(rows){return rows.length?`<div class="marketing-list">${rows.map(r=>`<article class="marketing-row">${r.image_data?`<img src="${esc(r.image_data)}" alt="${esc(r.outfit_name)}" loading="lazy">`:'<div class="marketing-image-placeholder" aria-label="No outfit photo">LM</div>'}<div class="marketing-copy"><div class="marketing-heading"><strong>${esc(r.influencer_name)}</strong>${badge(r.status)}</div><p>${esc(r.outfit_name)}</p><div class="marketing-details"><span>Agency: ${esc(r.agency_name||'—')}</span><span>Sent through: ${esc(r.sent_through||'—')}</span><span>Sent: ${date(r.sent_date)}</span><span>${esc(r.collaboration)}</span></div></div>${action('Edit',`data-edit="${r.id}" data-module="influencer_marketing"`)}</article>`).join('')}</div>`:empty('No collaborations yet','Add an influencer and outfit to get started.');}
function wireMarketing(){document.querySelector('#marketing-expand')?.addEventListener('click',()=>{marketingExpanded=!marketingExpanded;search='';render();});document.querySelector('#marketing-search')?.addEventListener('input',e=>{search=e.target.value;document.querySelector('#marketing-list').innerHTML=marketingList(data.influencer_marketing.filter(r=>marketingMatches(r,search)).sort((a,b)=>String(b.sent_date||b.created_at).localeCompare(String(a.sent_date||a.created_at))));bindRecords(document.querySelector('#marketing-list'));});}
function marketingForm(record={}){const fields=[['influencer_name','Influencer name','text',true],['outfit_name','Outfit name','text',true],['agency_name','Agency name (optional)','text'],['sent_through','Sent through (optional)','text'],['sent_date','Sent date (optional)','date'],['collaboration','Collaboration',['Barter','Sourcing'],true,'Barter'],['status','Status',['Planned','Sent','Received','Posted','Returned','Cancelled'],true,'Planned']];openModal(record.id?'Edit collaboration':'New collaboration',`<div class="form-grid">${fields.map(f=>field(f,record)).join('')}<label>Outfit photo (optional)<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label>${record.image_data?`<label class="photo-remove"><input type="checkbox" name="remove_photo">Remove current photo</label>`:''}</div>`,deleteButton('influencer_marketing',record.id),async f=>{const body=Object.fromEntries(fields.map(([key])=>[key,f.get(key)||null]));body.image_data=f.get('remove_photo')?null:record.image_data||null;const photo=await outfitPhoto(f.get('photo'));if(photo)body.image_data=photo;await rpc('save_marketing',{p_body:body,p_id:record.id||null});});}

let modalPageY=0;
function lockModalPage(){if(document.body.classList.contains('modal-open'))return;modalPageY=window.scrollY;document.body.style.top=-modalPageY+'px';document.body.classList.add('modal-open');}
function unlockModalPage(){if(document.querySelector('dialog[open]'))return;document.body.classList.remove('modal-open');document.body.style.top='';window.scrollTo(0,modalPageY);}
dialog.addEventListener('close',unlockModalPage);

function deleteButton(table,id){return can('owner')&&id?action('Delete',`type="button" data-delete-table="${table}" data-delete-id="${id}"`):'';}
function wireDelete(root=document){root.querySelectorAll('[data-delete-id]').forEach(b=>b.onclick=()=>deleteRecord(b.dataset.deleteTable,b.dataset.deleteId));}
async function deleteRecord(table,id){try{const preview=await rpc('delete_preview',{p_table:table,p_id:id});const labels={customers:'Clients',orders:'Orders',order_items:'Products',order_payments:'Client payments',purchases:'Purchases',purchase_payments:'Purchase payments',expenses:'Expenses',salary_profiles:'Salary profiles',salary_payouts:'Salary payments',salaries:'Salary periods',salary_payments:'Salary receipts',jobs:'Production jobs',tasks:'Tasks',events:'Calendar entries',studio_pieces:'Studio pieces',alterations:'Alterations',inventory:'Stock',influencer_marketing:'Collaborations'};const form=openModal('Delete entry?',`<p><strong>${esc(preview.label)}</strong></p><p class="helper">These entries will move to Deleted entries and be removed from active lists and totals. Restore them from More → Deleted entries.</p><ul class="delete-impact">${Object.entries(preview.counts).map(([table,count])=>`<li>${esc(labels[table]||table)} <strong>${count}</strong></li>`).join('')}</ul>`,'',async()=>{await rpc('delete_record',{p_table:table,p_id:id,p_token:preview.token});});form.querySelector('[type=submit]').textContent='Confirm Delete';}catch(err){notify(err.message);}}
let deletedEntries=[],deletedPageIndex=0;
function deletedPage(){setTimeout(loadDeleted,0);return section('Deleted entries',`<p class="helper">Restore an entry with its linked records.</p><div id="deleted-list"><p class="helper">Loading…</p></div>`);}
async function loadDeleted(){const list=document.querySelector('#deleted-list');if(!list)return;try{deletedEntries=await rpc('deleted_list');renderDeleted();}catch(e){list.textContent=e.message;}}
function renderDeleted(){const list=document.querySelector('#deleted-list');if(!list)return;const pages=Math.max(1,Math.ceil(deletedEntries.length/30));deletedPageIndex=Math.min(deletedPageIndex,pages-1);list.innerHTML=deletedEntries.length?`<div class="deleted-list">${deletedEntries.slice(deletedPageIndex*30,(deletedPageIndex+1)*30).map(r=>`<div><span><strong>${esc(r.label)}</strong><small>${esc(r.root_table.replaceAll('_',' '))} · ${r.count} entries · ${new Date(r.deleted_at).toLocaleDateString('en-IN')}</small></span>${action('Restore',`data-restore="${r.id}"`)}</div>`).join('')}</div>${pages>1?`<div class="record-pagination"><button data-trash-page="-1" ${deletedPageIndex===0?'disabled':''}>Previous</button><span>${deletedPageIndex+1} / ${pages}</span><button data-trash-page="1" ${deletedPageIndex>=pages-1?'disabled':''}>Next</button></div>`:''}`:empty('No deleted entries','Deleted studio entries will appear here.');list.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{const row=deletedEntries.find(r=>r.id===b.dataset.restore);const form=openModal('Restore entry?',`<p>${esc(row.label)} · ${row.count} entries</p>`,'',async()=>{await rpc('restore_record',{p_id:row.id});});form.querySelector('[type=submit]').textContent='Restore';});list.querySelectorAll('[data-trash-page]').forEach(b=>b.onclick=()=>{deletedPageIndex+=Number(b.dataset.trashPage);renderDeleted();});}
function quickExpenses(){const categories=expenseCategories.filter(c=>c!=='Salary'),rowHTML=i=>`<tr><td class="batch-number">${i}</td><td><select aria-label="Category row ${i}" data-batch-category><option value="">Select</option>${categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select><input data-manual-category aria-label="Manual category row ${i}" placeholder="Type category" maxlength="80" hidden></td><td><input aria-label="Description row ${i}" data-batch-description autocomplete="off" maxlength="300"></td><td><input aria-label="Amount row ${i}" data-batch-amount type="number" inputmode="decimal" min="0.01" step="0.01"></td></tr>`;const form=openModal('New expenses',`<div class="expense-batch"><div class="batch-options">${field(['expense_date','Date (optional)','date'])}${field(['paid_by','Paid by (optional)','text'])}${field(['payment_mode','Payment Mode (optional)',['','Cash','UPI','Bank transfer','Card']])}</div><div class="batch-scroll"><table class="batch-grid"><colgroup><col style="width:7%"><col style="width:27%"><col style="width:42%"><col style="width:24%"></colgroup><thead><tr><th>#</th><th>Category</th><th>Description</th><th>Amount</th></tr></thead><tbody>${[1,2,3].map(rowHTML).join('')}</tbody></table></div><button type="button" id="batch-add">+ Add More</button><div class="batch-total"><span>Total</span><strong id="batch-total">₹0</strong></div><small class="batch-help">Blank date records today. Empty rows are skipped.</small></div>`,'',async(f,form)=>{const rows=expenseBatch(readRows());await rpc('save_expense_batch',{p_rows:rows,p_date:f.get('expense_date')||null,p_paid_by:f.get('paid_by')||null,p_mode:f.get('payment_mode')||null});});const readRows=()=>[...form.querySelectorAll('.batch-grid tbody tr')].map(r=>({category:r.querySelector('[data-batch-category]').value==='Manual'?r.querySelector('[data-manual-category]').value.trim():r.querySelector('[data-batch-category]').value,description:r.querySelector('[data-batch-description]').value,amount:r.querySelector('[data-batch-amount]').value}));form.querySelector('#batch-add').onclick=()=>{const count=form.querySelectorAll('.batch-grid tbody tr').length;if(count>=100){notify('Save these expenses before adding more.');return;}form.querySelector('.batch-grid tbody').insertAdjacentHTML('beforeend',rowHTML(count+1));form.querySelector('.batch-grid tbody tr:last-child input').focus();};form.addEventListener('input',()=>{form.querySelector('#batch-total').textContent=money(batchTotal(readRows()));});form.addEventListener('change',e=>{if(!e.target.matches('[data-batch-category]'))return;const input=e.target.parentElement.querySelector('[data-manual-category]');input.hidden=e.target.value!=='Manual';input.required=e.target.value==='Manual';if(!input.hidden)input.focus();});form.querySelector('[type=submit]').textContent='Save expenses';form.addEventListener('keydown',e=>{if(e.key!=='Enter'||!e.target.matches('.batch-grid input'))return;e.preventDefault();const cells=[...form.querySelectorAll('.batch-grid select,.batch-grid input')],next=cells[cells.indexOf(e.target)+1];if(next)next.focus();else form.querySelector('#batch-add').click();});}
